/// Based on public domain keccak-f[1600] permutation.

const ROUNDS: usize = 24;

const RC: [u64; 24] = [
    0x0000000000000001,
    0x0000000000008082,
    0x800000000000808a,
    0x8000000080008000,
    0x000000000000808b,
    0x0000000080000001,
    0x8000000080008081,
    0x8000000000008009,
    0x000000000000008a,
    0x0000000000000088,
    0x0000000080008009,
    0x000000008000000a,
    0x000000008000808b,
    0x800000000000008b,
    0x8000000000008089,
    0x8000000000008003,
    0x8000000000008002,
    0x8000000000000080,
    0x000000000000800a,
    0x800000008000000a,
    0x8000000080008081,
    0x8000000000008080,
    0x0000000080000001,
    0x8000000080008008,
];

const ROT: [[u32; 5]; 5] = [
    [0, 36, 3, 41, 18],
    [1, 44, 10, 45, 2],
    [62, 6, 43, 15, 61],
    [28, 55, 25, 21, 56],
    [27, 20, 39, 8, 14],
];

fn rotl(x: u64, n: u32) -> u64 {
    x.rotate_left(n)
}

fn keccak_f(s: &mut [u64; 25]) {
    for round in 0..ROUNDS {
        // Theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = s[x] ^ s[x + 5] ^ s[x + 10] ^ s[x + 15] ^ s[x + 20];
        }
        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ rotl(c[(x + 1) % 5], 1);
        }
        for x in 0..5 {
            for y in 0..5 {
                s[x + 5 * y] ^= d[x];
            }
        }
        // Rho Pi
        let mut b = [0u64; 25];
        for x in 0..5 {
            for y in 0..5 {
                let new_x = y;
                let new_y = (2 * x + 3 * y) % 5;
                b[new_x + 5 * new_y] = rotl(s[x + 5 * y], ROT[x][y]);
            }
        }
        // Chi
        for x in 0..5 {
            for y in 0..5 {
                s[x + 5 * y] = b[x + 5 * y] ^ ((!b[(x + 1) % 5 + 5 * y]) & b[(x + 2) % 5 + 5 * y]);
            }
        }
        // Iota
        s[0] ^= RC[round];
    }
}

pub fn keccak256(input: &[u8]) -> [u8; 32] {
    let mut state = [0u64; 25];
    let rate = 1088 / 8; // 136 bytes for Keccak-256
    let mut offset = 0;
    let mut input = input;

    // Absorb full blocks
    while input.len() >= rate {
        for i in 0..(rate / 8) {
            let mut bytes = [0u8; 8];
            bytes.copy_from_slice(&input[i * 8..(i + 1) * 8]);
            state[i] ^= u64::from_le_bytes(bytes);
        }
        keccak_f(&mut state);
        input = &input[rate..];
        offset = 0;
    }

    // Last block + padding
    let mut block = [0u8; 136];
    block[..input.len()].copy_from_slice(input);
    block[input.len()] = 0x01;
    block[rate - 1] |= 0x80;
    for i in 0..(rate / 8) {
        let mut bytes = [0u8; 8];
        bytes.copy_from_slice(&block[i * 8..(i + 1) * 8]);
        state[i] ^= u64::from_le_bytes(bytes);
    }
    keccak_f(&mut state);

    // Squeeze 32 bytes
    let mut output = [0u8; 32];
    for i in 0..4 {
        output[i * 8..(i + 1) * 8].copy_from_slice(&state[i].to_le_bytes());
    }
    output
}

pub fn selector(signature: &str) -> String {
    let hash = keccak256(signature.as_bytes());
    // first 4 bytes hex
    format!("{:02x}{:02x}{:02x}{:02x}", hash[0], hash[1], hash[2], hash[3])
}
RS

"}

