fn extract_imports(content: &str) -> Vec<String> {
    let mut imports = Vec::new();
    // Simple regex for import "path" or import 'path' or import { ... } from "path" (not needed for solidity, but handle)
    // Solidity import syntax: import "path"; or import {symbol} from "path"; or import "path" as alias;
    // We'll just find all occurrences of import followed by string literal.
    let mut idx = 0;
    let chars: Vec<char> = content.chars().collect();
    while idx < content.len() {
        // Find "import"
        if content[idx..].starts_with("import") {
            // Ensure preceding char not alnum
            let prev_ok = if idx == 0 { true } else { !chars[idx-1].is_alphanumeric() && chars[idx-1] != '_' };
            if prev_ok {
                // Find next " or '
                let mut j = idx + 6;
                while j < content.len() && (content.as_bytes()[j] == b' ' || content.as_bytes()[j] == b'\t' || content.as_bytes()[j] == b'\n' || content.as_bytes()[j] == b'\r') {
                    j+=1;
                }
                // Check for { -> skip to from or string?
                // Look for string literal
                let mut found = None;
                // Search for " or ' in next 200 chars until ;
                let mut k = j;
                while k < content.len() && k < j+500 {
                    let c = content.as_bytes()[k];
                    if c == b'"' || c == b'\'' {
                        let quote = c;
                        let mut end = k+1;
                        while end < content.len() && content.as_bytes()[end] != quote {
                            end+=1;
                        }
                        if end < content.len() {
                            let path = &content[k+1..end];
                            found = Some(path.to_string());
                            break;
                        }
                    }
                    if c == b';' {
                        break;
                    }
                    k+=1;
                }
                if let Some(p) = found {
                    imports.push(p);
                }
                idx = j;
            }
        }
        idx+=1;
    }
    imports
}

fn resolve_import(import_path: &str, current_file: &str, base_path: &Option<PathBuf>, include_paths: &Vec<PathBuf>, remappings: &Vec<Remapping>) -> Result<String, String> {
    // First apply remappings
    let mut path = import_path.to_string();
    // Find longest matching prefix
    // Sort remappings by prefix length descending
    let mut sorted_remaps = remappings.clone();
    sorted_remaps.sort_by(|a,b| b.prefix.len().cmp(&a.prefix.len()));
    for remap in &sorted_remaps {
        // Check context
        if let Some(ctx) = &remap.context {
            // ctx should match current_file (full or suffix)
            if !current_file.ends_with(ctx) && current_file != ctx {
                continue;
            }
        }
        if path.starts_with(&remap.prefix) {
            let rest = &path[remap.prefix.len()..];
            let new_path = remap.path.join(rest);
            path = new_path.to_string_lossy().to_string();
            break;
        }
    }

    // If path is absolute, return it if exists
    if Path::new(&path).is_absolute() {
        if Path::new(&path).exists() {
            // Canonicalize?
            return Ok(path);
        } else {
            return Err(format!("file {} not found", import_path));
        }
    }

    // If path starts with "./" or "../", relative to current file
    if path.starts_with("./") || path.starts_with("../") {
        let current_dir = if current_file == "<stdin>" {
            PathBuf::from(".")
        } else {
            Path::new(current_file).parent().map(|p| p.to_path_buf()).unwrap_or(PathBuf::from("."))
        };
        let resolved = current_dir.join(&path);
        // Normalize (remove ./ and ../)
        let normalized = normalize_path(&resolved);
        if normalized.exists() {
            // Check base_path restriction for relative outside base
            if let Some(base) = base_path {
                let base_canon = base.canonicalize().unwrap_or(base.clone());
                let res_canon = normalized.canonicalize().unwrap_or(normalized.clone());
                if !res_canon.starts_with(&base_canon) {
                    // File outside base, should be blocked (return not found to match original behavior)
                    // Unless include_path contains it? But relative imports shouldn't use include_path.
                    return Err(format!("file {} not found", import_path));
                }
            }
            return Ok(normalized.to_string_lossy().to_string());
        } else {
            return Err(format!("file {} not found", import_path));
        }
    }

    // For bare imports (not starting with ./ ../ /), try:
    // 1. Relative to current file dir? Actually Solidity does NOT search current file dir for bare imports, only via include paths and base path.
    // But from earlier tests, "./Lib.sol" is relative and works, bare "Lib.sol" does NOT work without include path.
    // So for bare imports, we should NOT try current dir, only include paths and base path.

    // Try include paths
    for inc in include_paths {
        let candidate = inc.join(&path);
        if candidate.exists() {
            return Ok(candidate.to_string_lossy().to_string());
        }
    }
    // Try base_path
    if let Some(base) = base_path {
        let candidate = base.join(&path);
        if candidate.exists() {
            return Ok(candidate.to_string_lossy().to_string());
        }
    }
    // Try current file dir as fallback? For bare imports, original failed without include, so we should not try current dir for bare.
    // But we already tried relative case earlier. For bare, we already tried include and base, if not found, error.

    Err(format!("file {} not found", import_path))
}

fn normalize_path(p: &PathBuf) -> PathBuf {
    let mut components = Vec::new();
    for comp in p.components() {
        use std::path::Component;
        match comp {
            Component::ParentDir => {
                if let Some(last) = components.last() {
                    // Don't pop if last is Root or Prefix
                    components.pop();
                }
            },
            Component::CurDir => {},
            _ => components.push(comp),
        }
    }
    let mut res = PathBuf::new();
    for c in components {
        res.push(c);
    }
    res
}

