    // C3 linearization cache
    let mut lin_cache: HashMap<String, Vec<String>> = HashMap::new();

    fn c3_merge(mut lists: Vec<Vec<String>>) -> Vec<String> {
        let mut result = Vec::new();
        loop {
            lists.retain(|l| !l.is_empty());
            if lists.is_empty() { break; }
            let mut found = None;
            for i in 0..lists.len() {
                let candidate = lists[i][0].clone();
                let mut in_tail = false;
                for j in 0..lists.len() {
                    if lists[j].len()>1 && lists[j][1..].contains(&candidate) {
                        in_tail = true;
                        break;
                    }
                }
                if !in_tail {
                    found = Some(candidate);
                    break;
                }
            }
            if let Some(cand) = found {
                result.push(cand.clone());
                for lst in lists.iter_mut() {
                    if !lst.is_empty() && lst[0]==cand {
                        lst.remove(0);
                    }
                }
            } else {
                // Inconsistent, pick first
                let cand = lists[0][0].clone();
                result.push(cand.clone());
                for lst in lists.iter_mut() {
                    if !lst.is_empty() && lst[0]==cand {
                        lst.remove(0);
                    }
                }
            }
        }
        result
    }

    fn c3_linearize(name: &str, inheritance_map: &HashMap<String, Vec<String>>, cache: &mut HashMap<String, Vec<String>>) -> Vec<String> {
        if let Some(cached) = cache.get(name) {
            return cached.clone();
        }
        let direct_bases = inheritance_map.get(name).cloned().unwrap_or_default();
        let mut base_lins = Vec::new();
        for base in &direct_bases {
            let lin = c3_linearize(base, inheritance_map, cache);
            base_lins.push(lin);
        }
        let mut lists = base_lins.clone();
        let mut direct_rev = direct_bases.clone();
        direct_rev.reverse();
        lists.push(direct_rev);
        let merged = c3_merge(lists);
        let mut result = vec![name.to_string()];
        result.extend(merged);
        // Dedup preserving first
        let mut seen = HashSet::new();
        let mut uniq = Vec::new();
        for item in result {
            if seen.insert(item.clone()) {
                uniq.push(item);
            }
        }
        cache.insert(name.to_string(), uniq.clone());
        uniq
    }

    // For each contract, compute abi
    let mut contracts_output: BTreeMap<String, serde_json::Value> = BTreeMap::new();

    for (full_name, contract) in &contract_db {
        // Compute linearization
        let lin = c3_linearize(full_name, &inheritance_map, &mut lin_cache);

        // Collect items
        // Constructor: only from self
        let mut ctor: Option<ConstructorInfo> = contract.constructor.clone();

        // Fallback and receive: first in lin
        let mut fallback: Option<FallbackInfo> = None;
        let mut receive: Option<ReceiveInfo> = None;
        for lin_name in &lin {
            if let Some(c) = contract_db.get(lin_name) {
                if fallback.is_none() {
                    if let Some(fb) = &c.fallback {
                        fallback = Some(fb.clone());
                    }
                }
                if receive.is_none() {
                    if let Some(rcv) = &c.receive {
                        receive = Some(rcv.clone());
                    }
                }
            }
        }

        // Errors and events: collect with dedup checks
        let mut errors: Vec<ErrorInfo> = Vec::new();
