                        fn canonical_from_abi_value(v: &serde_json::Value) -> String {
                            let type_str = v["type"].as_str().unwrap_or("");
                            if type_str.starts_with("tuple") {
                                let suffix = &type_str["tuple".len()..];
                                let comps = v.get("components");
                                let inner = if let Some(comps) = comps {
                                    if let Some(arr) = comps.as_array() {
                                        arr.iter().map(|c| canonical_from_abi_value(c)).collect::<Vec<_>>().join(",")
                                    } else {
                                        "".to_string()
                                    }
                                } else {
                                    "".to_string()
                                };
                                format!("({}){}", inner, suffix)
                            } else {
                                type_str.to_string()
                            }
                        }

                        let ct = canonical_from_abi_value(inp);
                        canonical_types.push(ct);
                    }
                    let sig = format!("{}({})", name, canonical_types.join(","));
                    let sel = selector(&sig);
                    hashes_map.insert(sig, sel);
                }
            }
            // Sort hashes by signature alphabetical (BTreeMap does)
            contract_entry["hashes"] = json!(hashes_map);
        }

        contracts_output.insert(contract_key, contract_entry);
    }

    // Build final JSON
    let final_json = json!({
        "contracts": contracts_output,
        "version": "0.1.8"
    });

    // Output handling: if out_dir set, write to combined.json, else stdout
    if let Some(out_dir_path) = cli.out_dir {
        // Check if out_dir exists and is dir
        if !out_dir_path.exists() {
            eprintln!("error: failed to write to output: No such file or directory (os error 2)\n\nerror: aborting due to 1 previous error\n");
            std::process::exit(1);
        }
        if !out_dir_path.is_dir() {
            eprintln!("error: failed to write to output: Not a directory (os error 20)\n\nerror: aborting due to 1 previous error\n");
            std::process::exit(1);
        }
        let combined_path = out_dir_path.join("combined.json");
        let json_str = if cli.pretty_json {
            serde_json::to_string_pretty(&final_json).unwrap()
        } else {
            final_json.to_string()
        };
        if let Err(e) = fs::write(combined_path, json_str) {
            eprintln!("error: failed to write to output: {} (os error {})\n\nerror: aborting due to 1 previous error\n", e, e.raw_os_error().unwrap_or(0));
            std::process::exit(1);
        }
    } else {
        let json_str = if cli.pretty_json {
            serde_json::to_string_pretty(&final_json).unwrap()
        } else {
            final_json.to_string()
        };
        println!("{}", json_str);
    }
}

fn generate_getter_inputs_outputs(sv: &StateVarInfo, structs: &HashMap<String, StructInfo>, enums: &HashMap<String, EnumInfo>, contract_name: &str) -> (Vec<AbiParam>, Vec<AbiParam>) {
    // Parse sv.type_str which may be mapping, array, etc.
    // We need to peel mapping keys and array indices

    let mut inputs = Vec::new();
    let mut current_type_str = sv.type_str.clone();

    // Peel mappings
    loop {
        let trimmed = current_type_str.trim();
        if trimmed.starts_with("mapping") {
            // Extract key and value
            // mapping(key => value)
            if let Some(start) = trimmed.find('(') {
                if let Some(end) = trimmed.rfind(')') {
                    let inner = &trimmed[start+1..end];
                    // Find "=>"
                    if let Some(arrow) = inner.find("=>") {
                        let key_type = inner[..arrow].trim().to_string();
                        let value_type = inner[arrow+2..].trim().to_string();
                        // Key type to abi
                        let key_abi = solidity_type_to_abi(&key_type, contract_name, structs, enums);
                        inputs.push(key_abi);
                        current_type_str = value_type;
                        continue;
                    }
                }
            }
            break;
        } else {
            break;
        }
    }

    // Peel arrays
    loop {
        let (base, suffixes) = extract_array_suffix(&current_type_str);
        if !suffixes.is_empty() {
            // For each suffix, add uint256 input
            for _ in &suffixes {
                // For array getter, input is uint256 index
                inputs.push(AbiParam {
                    name: "".to_string(),
                    type_: "uint256".to_string(),
                    internal_type: "uint256".to_string(),
                    indexed: None,
                    components: None,
                });
            }
            current_type_str = base;
        } else {
            break;
        }
    }

    // Now current_type_str is final return type
    // If it's struct, expand its members into outputs
    let abi_param = solidity_type_to_abi(&current_type_str, contract_name, structs, enums);
    let mut outputs = Vec::new();
    if abi_param.type_ == "tuple" {
        // If struct, expand members? According to earlier observation, for top-level struct getter, outputs are its members expanded, not single tuple
        // But for nested struct member, we already handled? Actually for getter of struct type, we should expand its members as outputs (each member as AbiParam)
        if let Some(comps) = abi_param.components {
            // Each component is already AbiParam with name and type
            for comp in comps {
                outputs.push(comp);
            }
        } else {
            outputs.push(abi_param);
        }
    } else {
        // Single output
        let mut out = abi_param;
        out.name = "".to_string(); // getter outputs have empty name? For simple var, name ""? In earlier output for simple getter, name was "" for return? Actually for public var getter, outputs have name "" for simple, but for struct getter with members, names are member names. We already have that.
        outputs.push(out);
    }

    (inputs, outputs)
}
