        };
        let obj = json!({
            "sourceLocation": null,
            "secondarySourceLocations": [],
            "type": "Exception",
            "component": "general",
            "severity": "error",
            "errorCode": null,
            "message": msg,
            "formattedMessage": formatted
        });
        if pretty_err {
            println!("{}", serde_json::to_string_pretty(&obj).unwrap());
        } else {
            println!("{}", obj.to_string());
        }
    } else if error_format == "rustc-json" {
