fn extract_imports(content: &str) -> Vec<String> {
    let mut imports = Vec::new();
    // Simple regex for import "path" or import 'path' or import { ... } from "path" (not needed for solidity, but handle)
    // Solidity import syntax: import "path"; or import {symbol} from "path"; or import "path" as alias;
    // We'll just find all occurrences of import followed by string literal.
    let mut idx = 0;
    let chars: Vec<char> = content.chars().collect();
    while idx < content.len() {
        // Find "import"
        if content[idx..].starts_with("import") {
            // Ensure preceding char not alnum
            let prev_ok = if idx == 0 { true } else { !chars[idx-1].is_alphanumeric() && chars[idx-1] != '_' };
            if prev_ok {
                // Find next " or '
                let mut j = idx + 6;
                while j < content.len() && (content.as_bytes()[j] == b' ' || content.as_bytes()[j] == b'\t' || content.as_bytes()[j] == b'\n' || content.as_bytes()[j] == b'\r') {
                    j+=1;
                }
                // Check for { -> skip to from or string?
                // Look for string literal
                let mut found = None;
                // Search for " or ' in next 200 chars until ;
                let mut k = j;
                while k < content.len() && k < j+500 {
                    let c = content.as_bytes()[k];
                    if c == b'"' || c == b'\'' {
                        let quote = c;
                        let mut end = k+1;
                        while end < content.len() && content.as_bytes()[end] != quote {
                            end+=1;
                        }
                        if end < content.len() {
                            let path = &content[k+1..end];
                            found = Some(path.to_string());
                            break;
                        }
                    }
                    if c == b';' {
                        break;
                    }
                    k+=1;
                }
                if let Some(p) = found {
                    imports.push(p);
                }
                idx = j;
            }
        }
        idx+=1;
    }
    imports
}

fn resolve_import(import_path: &str, current_file: &str, base_path: &Option<PathBuf>, include_paths: &Vec<PathBuf>, remappings: &Vec<Remapping>) -> Result<String, String> {
    // First apply remappings
    let mut path = import_path.to_string();
    // Find longest matching prefix
    // Sort remappings by prefix length descending
    let mut sorted_remaps = remappings.clone();
    sorted_remaps.sort_by(|a,b| b.prefix.len().cmp(&a.prefix.len()));
    for remap in &sorted_remaps {
        // Check context
        if let Some(ctx) = &remap.context {
            // ctx should match current_file (full or suffix)
            if !current_file.ends_with(ctx) && current_file != ctx {
                continue;
            }
        }
        if path.starts_with(&remap.prefix) {
            let rest = &path[remap.prefix.len()..];
            let new_path = remap.path.join(rest);
            path = new_path.to_string_lossy().to_string();
            break;
        }
    }

    // If path is absolute, return it if exists
    if Path::new(&path).is_absolute() {
        if Path::new(&path).exists() {
            // Canonicalize?
            return Ok(path);
        } else {
            return Err(format!("file {} not found", import_path));
        }
    }

    // If path starts with "./" or "../", relative to current file
    if path.starts_with("./") || path.starts_with("../") {
        let current_dir = if current_file == "<stdin>" {
            PathBuf::from(".")
        } else {
            Path::new(current_file).parent().map(|p| p.to_path_buf()).unwrap_or(PathBuf::from("."))
        };
        let resolved = current_dir.join(&path);
        // Normalize (remove ./ and ../)
        let normalized = normalize_path(&resolved);
        if normalized.exists() {
            // Check base_path restriction for relative outside base
            if let Some(base) = base_path {
                let base_canon = base.canonicalize().unwrap_or(base.clone());
                let res_canon = normalized.canonicalize().unwrap_or(normalized.clone());
                if !res_canon.starts_with(&base_canon) {
                    // File outside base, should be blocked (return not found to match original behavior)
                    // Unless include_path contains it? But relative imports shouldn't use include_path.
                    return Err(format!("file {} not found", import_path));
                }
            }
            return Ok(normalized.to_string_lossy().to_string());
        } else {
            return Err(format!("file {} not found", import_path));
        }
    }

    // For bare imports (not starting with ./ ../ /), try:
    // 1. Relative to current file dir? Actually Solidity does NOT search current file dir for bare imports, only via include paths and base path.
    // But from earlier tests, "./Lib.sol" is relative and works, bare "Lib.sol" does NOT work without include path.
    // So for bare imports, we should NOT try current dir, only include paths and base path.

    // Try include paths
    for inc in include_paths {
        let candidate = inc.join(&path);
        if candidate.exists() {
            return Ok(candidate.to_string_lossy().to_string());
        }
    }
    // Try base_path
    if let Some(base) = base_path {
        let candidate = base.join(&path);
        if candidate.exists() {
            return Ok(candidate.to_string_lossy().to_string());
        }
    }
    // Try current file dir as fallback? For bare imports, original failed without include, so we should not try current dir for bare.
    // But we already tried relative case earlier. For bare, we already tried include and base, if not found, error.

    Err(format!("file {} not found", import_path))
}

fn normalize_path(p: &PathBuf) -> PathBuf {
    let mut components = Vec::new();
    for comp in p.components() {
        use std::path::Component;
        match comp {
            Component::ParentDir => {
                if let Some(last) = components.last() {
                    // Don't pop if last is Root or Prefix
                    components.pop();
                }
            },
            Component::CurDir => {},
            _ => components.push(comp),
        }
    }
    let mut res = PathBuf::new();
    for c in components {
        res.push(c);
    }
    res
}

// Solidity parsing structures
#[derive(Debug, Clone)]
struct StructInfo {
    name: String,
    members: Vec<(String, String)>, // (name, type_str)
}

#[derive(Debug, Clone)]
struct EnumInfo {
    name: String,
    variants: Vec<String>,
}

#[derive(Debug, Clone)]
struct Param {
    name: String,
    type_str: String, // original type string
    indexed: bool,
}

#[derive(Debug, Clone)]
struct FunctionInfo {
    name: String,
    params: Vec<Param>,
    returns: Vec<Param>,
    visibility: String, // public, external, internal, private
    mutability: String, // payable, view, pure, nonpayable
    is_constructor: bool,
    is_fallback: bool,
    is_receive: bool,
    is_virtual: bool,
    overrides: Vec<String>,
}

#[derive(Debug, Clone)]
struct EventInfo {
    name: String,
    params: Vec<Param>,
    anonymous: bool,
}

#[derive(Debug, Clone)]
struct ErrorInfo {
    name: String,
    params: Vec<Param>,
}

#[derive(Debug, Clone)]
struct StateVarInfo {
    name: String,
    type_str: String,
    visibility: String,
    is_constant: bool,
}

#[derive(Debug, Clone)]
struct ConstructorInfo {
    params: Vec<Param>,
    mutability: String,
    is_payable: bool,
}

#[derive(Debug, Clone)]
struct FallbackInfo {
    mutability: String,
    is_virtual: bool,
    overrides: Vec<String>,
}

#[derive(Debug, Clone)]
struct ReceiveInfo {
    is_virtual: bool,
    overrides: Vec<String>,
}

#[derive(Debug, Clone)]
struct ContractInfo {
    name: String,
    bases: Vec<String>,
    functions: Vec<FunctionInfo>,
    events: Vec<EventInfo>,
    errors: Vec<ErrorInfo>,
    state_vars: Vec<StateVarInfo>,
    structs: HashMap<String, StructInfo>,
    enums: HashMap<String, EnumInfo>,
    constructor: Option<ConstructorInfo>,
    fallback: Option<FallbackInfo>,
    receive: Option<ReceiveInfo>,
}

fn parse_contracts(content: &str, file_path: &str) -> Vec<ContractInfo> {
    let mut contracts = Vec::new();
    // Remove comments for easier parsing? We need to keep string literals but we will handle.
    let cleaned = remove_comments(content);
    // Find contract definitions
    let mut idx = 0;
    let chars: Vec<char> = cleaned.chars().collect();
    while idx < cleaned.len() {
        // Look for contract, interface, library keywords
        if let Some(pos) = find_keyword(&cleaned, idx, &["contract", "interface", "library"]) {
            let kw = &cleaned[pos..pos+8].trim_start();
            // Actually find which keyword
            let mut keyword = "";
            let mut kw_len = 0;
            for k in ["contract", "interface", "library"] {
                if cleaned[pos..].starts_with(k) {
                    keyword = k;
                    kw_len = k.len();
                    break;
                }
            }
            if keyword.is_empty() {
                idx = pos+1;
                continue;
            }
            // After keyword, parse name
            let mut j = pos + kw_len;
            while j < cleaned.len() && cleaned.as_bytes()[j].is_ascii_whitespace() {
                j+=1;
            }
            // Name
            let name_start = j;
            while j < cleaned.len() && (cleaned.as_bytes()[j].is_ascii_alphanumeric() || cleaned.as_bytes()[j] == b'_') {
                j+=1;
            }
            let name = cleaned[name_start..j].to_string();
            if name.is_empty() {
                idx = j;
                continue;
            }
            // Skip whitespace
            while j < cleaned.len() && cleaned.as_bytes()[j].is_ascii_whitespace() {
                j+=1;
            }
            // Check for "is" clause
            let mut bases = Vec::new();
            if j+2 < cleaned.len() && cleaned[j..].starts_with("is") && (cleaned.as_bytes()[j+2].is_ascii_whitespace() || cleaned.as_bytes()[j+2] == b'{' || cleaned.as_bytes()[j+2] == b'/') {
                j+=2;
                while j < cleaned.len() && cleaned.as_bytes()[j].is_ascii_whitespace() {
                    j+=1;
                }
                // Bases list until '{'
                let bases_start = j;
                let mut brace_pos = None;
                let mut paren_depth = 0;
                while j < cleaned.len() {
                    let c = cleaned.as_bytes()[j];
                    if c == b'(' {
                        paren_depth+=1;
                    } else if c == b')' {
                        if paren_depth>0 { paren_depth-=1; }
                    } else if c == b'{' && paren_depth==0 {
                        brace_pos = Some(j);
                        break;
                    }
                    j+=1;
                }
                if let Some(bp) = brace_pos {
                    let bases_str = cleaned[bases_start..bp].trim();
                    // Split by comma
                    for base in bases_str.split(',') {
                        let base = base.trim();
                        if base.is_empty() { continue; }
                        // Extract base name before '('
                        let base_name = if let Some(p) = base.find('(') {
                            base[..p].trim()
                        } else {
                            base
                        };
                        // base name may have spaces? Take last word?
                        let bn = base_name.split_whitespace().last().unwrap_or(base_name).to_string();
                        bases.push(bn);
                    }
                    j = bp;
                }
            }
            // Now j should be at '{'
            if j >= cleaned.len() || cleaned.as_bytes()[j] != b'{' {
                // Find '{'
                while j < cleaned.len() && cleaned.as_bytes()[j] != b'{' {
                    j+=1;
                }
            }
            if j >= cleaned.len() {
                break;
            }
            // Find matching '}'
            let body_start = j+1;
            let mut depth = 1;
            let mut k = body_start;
            while k < cleaned.len() && depth>0 {
                let c = cleaned.as_bytes()[k];
                if c == b'{' {
                    depth+=1;
                } else if c == b'}' {
                    depth-=1;
                }
                k+=1;
            }
            let body_end = if depth==0 { k-1 } else { cleaned.len() };
            let body = cleaned[body_start..body_end].to_string();
            let contract = parse_contract_body(&name, bases, &body);
            contracts.push(contract);
            idx = body_end+1;
        } else {
            break;
        }
    }
    contracts
}

fn find_keyword(s: &str, start: usize, keywords: &[&str]) -> Option<usize> {
    let mut idx = start;
    while idx < s.len() {
        for kw in keywords {
            if s[idx..].starts_with(kw) {
                // Check preceding char not alnum
                if idx>0 {
                    let prev = s.as_bytes()[idx-1];
                    if prev.is_ascii_alphanumeric() || prev == b'_' {
                        continue;
                    }
                }
                // Check next char not alnum
                let next_idx = idx + kw.len();
                if next_idx < s.len() {
                    let next = s.as_bytes()[next_idx];
                    if next.is_ascii_alphanumeric() || next == b'_' {
                        continue;
                    }
                }
                return Some(idx);
            }
        }
        idx+=1;
    }
    None
}

fn remove_comments(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    let mut in_single = false;
    let mut in_multi = false;
    let mut in_string = false;
    let mut string_char = '"';
    while let Some(c) = chars.next() {
        if in_single {
            if c == '\n' {
                in_single = false;
                result.push(c);
            }
            continue;
        }
        if in_multi {
            if c == '*' {
                if let Some(&next) = chars.peek() {
                    if next == '/' {
                        chars.next();
                        in_multi = false;
                    }
                }
            }
            continue;
        }
        if in_string {
            result.push(c);
            if c == string_char && !result.ends_with("\\\"") && !result.ends_with("\\'") {
                // Check if escaped?
                // Simplified: if previous char not backslash
                // We already pushed, need to check previous char in original
                // For simplicity, end string
                in_string = false;
            }
            continue;
        }
        if c == '/' {
            if let Some(&next) = chars.peek() {
                if next == '/' {
                    chars.next();
                    in_single = true;
                    continue;
                } else if next == '*' {
                    chars.next();
                    in_multi = true;
                    continue;
                }
            }
            result.push(c);
        } else if c == '"' || c == '\'' {
            in_string = true;
            string_char = c;
            result.push(c);
        } else {
            result.push(c);
        }
    }
    result
}

fn parse_contract_body(name: &str, bases: Vec<String>, body: &str) -> ContractInfo {
    let mut contract = ContractInfo {
        name: name.to_string(),
        bases,
        functions: Vec::new(),
        events: Vec::new(),
        errors: Vec::new(),
        state_vars: Vec::new(),
        structs: HashMap::new(),
        enums: HashMap::new(),
        constructor: None,
        fallback: None,
        receive: None,
    };

    // Parse structs
    // regex for struct: struct Name { ... }
    let mut remaining = body.to_string();
    // Use simple scanning for struct and enum to avoid overlapping
    // We'll extract structs via manual search
    let mut idx = 0;
    while idx < remaining.len() {
        if let Some(pos) = remaining[idx..].find("struct") {
            let abs_pos = idx + pos;
            // Check keyword boundaries
            if abs_pos>0 && (remaining.as_bytes()[abs_pos-1].is_ascii_alphanumeric() || remaining.as_bytes()[abs_pos-1]==b'_') {
                idx = abs_pos+6;
                continue;
            }
            let after = &remaining[abs_pos+6..];
            let mut j = 0;
            while j < after.len() && after.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            let name_start = j;
            while j < after.len() && (after.as_bytes()[j].is_ascii_alphanumeric() || after.as_bytes()[j]==b'_') { j+=1; }
            let struct_name = after[name_start..j].to_string();
            // Find {
            while j < after.len() && after.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            if j>=after.len() || after.as_bytes()[j]!=b'{' { idx = abs_pos+6; continue; }
            let body_start = j+1;
            let mut depth = 1;
            let mut k = body_start;
            while k < after.len() && depth>0 {
                if after.as_bytes()[k]==b'{' { depth+=1; }
                else if after.as_bytes()[k]==b'}' { depth-=1; }
                k+=1;
            }
            let struct_body = after[body_start..k-1].to_string();
            // Parse members: split by ';'
            let mut members = Vec::new();
            for line in struct_body.split(';') {
                let line = line.trim();
                if line.is_empty() { continue; }
                // Member: type name
                // Example: uint256 a
                // or mapping? struct members cannot be mapping? But we handle.
                // Find last identifier as name
                if let Some(last_space) = line.rfind(|c: char| c.is_whitespace()) {
                    let name_part = line[last_space+1..].trim();
                    let type_part = line[..last_space].trim();
                    if !name_part.is_empty() && !type_part.is_empty() {
                        // name should be identifier
                        if name_part.chars().all(|c| c.is_alphanumeric() || c=='_') {
                            members.push((name_part.to_string(), type_part.to_string()));
                        }
                    }
                }
            }
            contract.structs.insert(struct_name.clone(), StructInfo { name: struct_name, members });
            idx = abs_pos+6;
        } else {
            break;
        }
    }
    // Enums
    idx = 0;
    while idx < remaining.len() {
        if let Some(pos) = remaining[idx..].find("enum") {
            let abs_pos = idx + pos;
            if abs_pos>0 && (remaining.as_bytes()[abs_pos-1].is_ascii_alphanumeric() || remaining.as_bytes()[abs_pos-1]==b'_') {
                idx = abs_pos+4;
                continue;
            }
            let after = &remaining[abs_pos+4..];
            let mut j = 0;
            while j < after.len() && after.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            let name_start = j;
            while j < after.len() && (after.as_bytes()[j].is_ascii_alphanumeric() || after.as_bytes()[j]==b'_') { j+=1; }
            let enum_name = after[name_start..j].to_string();
            while j < after.len() && after.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            if j>=after.len() || after.as_bytes()[j]!=b'{' { idx=abs_pos+4; continue; }
            let body_start = j+1;
            let mut depth=1;
            let mut k=body_start;
            while k<after.len() && depth>0 {
                if after.as_bytes()[k]==b'{' { depth+=1; }
                else if after.as_bytes()[k]==b'}' { depth-=1; }
                k+=1;
            }
            let enum_body = after[body_start..k-1].to_string();
            let variants: Vec<String> = enum_body.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
            contract.enums.insert(enum_name.clone(), EnumInfo { name: enum_name, variants });
            idx = abs_pos+4;
        } else { break; }
    }

    // Now parse rest of body for functions, events, errors, state vars, constructor, fallback, receive
    // We'll scan through body character by character, tracking brace depth to find top-level items.

    let mut i = 0;
    let body_bytes = body.as_bytes();
    let body_len = body.len();
    while i < body_len {
        // Skip whitespace and comments already removed? We removed comments but still have whitespace.
        while i < body_len && body_bytes[i].is_ascii_whitespace() {
            i+=1;
        }
        if i>=body_len { break; }

        // Check what keyword at position
        let remaining_slice = &body[i..];
        if remaining_slice.starts_with("function") && (i==0 || !body_bytes[i-1].is_ascii_alphanumeric()) {
            // Parse function
            if let Some((func, next_idx)) = parse_function(&body, i) {
                contract.functions.push(func);
                i = next_idx;
                continue;
            }
        } else if remaining_slice.starts_with("constructor") {
            if let Some((ctor, next_idx)) = parse_constructor(&body, i) {
                contract.constructor = Some(ctor);
                i = next_idx;
                continue;
            }
        } else if remaining_slice.starts_with("fallback") {
            if let Some((fb, next_idx)) = parse_fallback(&body, i) {
                contract.fallback = Some(fb);
                i = next_idx;
                continue;
            }
        } else if remaining_slice.starts_with("receive") {
            if let Some((rcv, next_idx)) = parse_receive(&body, i) {
                contract.receive = Some(rcv);
                i = next_idx;
                continue;
            }
        } else if remaining_slice.starts_with("event") {
            if let Some((ev, next_idx)) = parse_event(&body, i) {
                contract.events.push(ev);
                i = next_idx;
                continue;
            }
        } else if remaining_slice.starts_with("error") {
            if let Some((err, next_idx)) = parse_error(&body, i) {
                contract.errors.push(err);
                i = next_idx;
                continue;
            }
        } else if remaining_slice.starts_with("struct") || remaining_slice.starts_with("enum") || remaining_slice.starts_with("modifier") || remaining_slice.starts_with("using") {
            // Skip these items (already handled structs/enums, skip modifier and using)
            // Find either ';' or matching '}'
            let mut j = i;
            let mut found_brace = false;
            while j < body_len {
                if body_bytes[j]==b'{' {
                    found_brace = true;
                    break;
                }
                if body_bytes[j]==b';' {
                    break;
                }
                j+=1;
            }
            if found_brace {
                // Find matching }
                let mut depth = 1;
                j+=1;
                while j < body_len && depth>0 {
                    if body_bytes[j]==b'{' { depth+=1; }
                    else if body_bytes[j]==b'}' { depth-=1; }
                    j+=1;
                }
                i = j;
            } else {
                // Up to ;
                while j < body_len && body_bytes[j]!=b';' { j+=1; }
                if j < body_len { j+=1; }
                i = j;
            }
            continue;
        } else {
            // Try state var: look for ';' at depth 0
            // Find next ';' that is not inside parens? State var ends with ';' at top level.
            // We need to find ';' and ensure before that there's no '{' that starts function etc.
            // For simplicity, find next ';'
            if let Some(semi_pos) = find_next_semicolon(&body, i) {
                let line = body[i..semi_pos+1].to_string();
                // Check if line contains "function" or "event" etc already handled, but we are in else, so try state var
                if let Some(sv) = parse_state_var(&line) {
                    contract.state_vars.push(sv);
                }
                i = semi_pos+1;
                continue;
            } else {
                break;
            }
        }
        i+=1;
    }

    contract
}

fn find_next_semicolon(body: &str, start: usize) -> Option<usize> {
    let bytes = body.as_bytes();
    let mut i = start;
    let mut paren_depth = 0;
    let mut brace_depth = 0;
    while i < body.len() {
        let c = bytes[i];
        if c == b'(' {
            paren_depth+=1;
        } else if c == b')' {
            if paren_depth>0 { paren_depth-=1; }
        } else if c == b'{' {
            brace_depth+=1;
        } else if c == b'}' {
            if brace_depth>0 { brace_depth-=1; }
        } else if c == b';' && paren_depth==0 && brace_depth==0 {
            return Some(i);
        }
        i+=1;
    }
    None
}

fn parse_function(body: &str, start: usize) -> Option<(FunctionInfo, usize)> {
    // body[start..] starts with "function"
    let remaining = &body[start..];
    // Find '(' for params
    let func_kw_len = "function".len();
    let mut idx = func_kw_len;
    while idx < remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    // Function name (optional)
    let name_start = idx;
    while idx < remaining.len() && (remaining.as_bytes()[idx].is_ascii_alphanumeric() || remaining.as_bytes()[idx]==b'_') { idx+=1; }
    let func_name = if name_start!=idx { remaining[name_start..idx].to_string() } else { "".to_string() };

    // Skip whitespace
    while idx < remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    if idx>=remaining.len() || remaining.as_bytes()[idx]!=b'(' { return None; }
    // Find matching ')'
    let params_start = idx+1;
    let mut depth = 1;
    let mut j = params_start;
    while j < remaining.len() && depth>0 {
        let c = remaining.as_bytes()[j];
        if c==b'(' { depth+=1; }
        else if c==b')' { depth-=1; }
        j+=1;
    }
    if depth!=0 { return None; }
    let params_end = j-1;
    let params_str = remaining[params_start..params_end].to_string();

    // After params, parse modifiers until '{' or ';'
    let mut k = j;
    while k < remaining.len() && remaining.as_bytes()[k].is_ascii_whitespace() { k+=1; }
    // Find either '{' or ';' that terminates signature
    let mut sig_end = None;
    let mut brace_pos = None;
    let mut paren_depth = 0;
    let mut temp_k = k;
    while temp_k < remaining.len() {
        let c = remaining.as_bytes()[temp_k];
        if c==b'(' { paren_depth+=1; }
        else if c==b')' { if paren_depth>0 { paren_depth-=1; } }
        else if c==b'{' && paren_depth==0 {
            sig_end = Some(temp_k);
            brace_pos = Some(temp_k);
            break;
        } else if c==b';' && paren_depth==0 {
            sig_end = Some(temp_k);
            break;
        }
        temp_k+=1;
    }
    let sig_end_idx = sig_end.unwrap_or(remaining.len());
    let modifiers_str = remaining[k..sig_end_idx].to_string();

    // Parse visibility and mutability from modifiers_str
    let visibility = extract_visibility(&modifiers_str);
    let mutability = extract_mutability(&modifiers_str);
    let is_virtual = modifiers_str.contains("virtual");
    let overrides = extract_overrides(&modifiers_str);
    let returns = extract_returns(&modifiers_str);

    let params = parse_params(&params_str);
    let returns_parsed = if returns.is_empty() { Vec::new() } else { parse_params(&returns) };

    // Find end of function: if brace, find matching '}'
    let mut next_idx = start + sig_end_idx;
    let mut final_idx = next_idx;
    if let Some(bp) = brace_pos {
        // Find matching }
        let mut depth = 1;
        let mut p = start + bp +1;
        while p < body.len() && depth>0 {
            let c = body.as_bytes()[p];
            if c==b'{' { depth+=1; }
            else if c==b'}' { depth-=1; }
            p+=1;
        }
        final_idx = p;
    } else {
        // Ends with ';'
        if next_idx < body.len() && body.as_bytes()[next_idx]==b';' {
            final_idx = next_idx+1;
        }
    }

    let func = FunctionInfo {
        name: func_name,
        params,
        returns: returns_parsed,
        visibility: visibility.unwrap_or("public".to_string()), // default?
        mutability,
        is_constructor: false,
        is_fallback: false,
        is_receive: false,
        is_virtual,
        overrides,
    };
    Some((func, final_idx))
}

fn parse_constructor(body: &str, start: usize) -> Option<(ConstructorInfo, usize)> {
    let remaining = &body[start..];
    let kw_len = "constructor".len();
    let mut idx = kw_len;
    while idx < remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    if idx>=remaining.len() || remaining.as_bytes()[idx]!=b'(' { return None; }
    let params_start = idx+1;
    let mut depth=1;
    let mut j=params_start;
    while j<remaining.len() && depth>0 {
        let c=remaining.as_bytes()[j];
        if c==b'(' { depth+=1; } else if c==b')' { depth-=1; }
        j+=1;
    }
    let params_str = remaining[params_start..j-1].to_string();
    let mut k=j;
    while k<remaining.len() && remaining.as_bytes()[k].is_ascii_whitespace() { k+=1; }
    // Find { or ;
    let mut sig_end=None;
    let mut brace_pos=None;
    let mut temp=k;
    let mut pd=0;
    while temp<remaining.len() {
        let c=remaining.as_bytes()[temp];
        if c==b'(' { pd+=1; } else if c==b')' { if pd>0 { pd-=1; } }
        else if c==b'{' && pd==0 { sig_end=Some(temp); brace_pos=Some(temp); break; }
        else if c==b';' && pd==0 { sig_end=Some(temp); break; }
        temp+=1;
    }
    let sig_end_idx = sig_end.unwrap_or(remaining.len());
    let modifiers_str = remaining[k..sig_end_idx].to_string();
    let mutability = extract_mutability(&modifiers_str);
    let params = parse_params(&params_str);

    let mut final_idx = start + sig_end_idx;
    if let Some(bp) = brace_pos {
        let mut depth=1;
        let mut p=start+bp+1;
        while p<body.len() && depth>0 {
            let c=body.as_bytes()[p];
            if c==b'{' { depth+=1; } else if c==b'}' { depth-=1; }
            p+=1;
        }
        final_idx=p;
    } else {
        if final_idx<body.len() && body.as_bytes()[final_idx]==b';' { final_idx+=1; }
    }

    let ctor = ConstructorInfo {
        params,
        mutability: mutability.clone(),
        is_payable: mutability=="payable",
    };
    Some((ctor, final_idx))
}

fn parse_fallback(body: &str, start: usize) -> Option<(FallbackInfo, usize)> {
    let remaining = &body[start..];
    let kw_len = "fallback".len();
    let mut idx=kw_len;
    while idx<remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    // Expect '('
    if idx<remaining.len() && remaining.as_bytes()[idx]==b'(' {
        // Find ')'
        let mut depth=1;
        let mut j=idx+1;
        while j<remaining.len() && depth>0 {
            let c=remaining.as_bytes()[j];
            if c==b'(' { depth+=1; } else if c==b')' { depth-=1; }
            j+=1;
        }
        idx=j;
    }
    // Skip whitespace
    while idx<remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    // Find { or ;
    let mut sig_end=None;
    let mut brace_pos=None;
    let mut temp=idx;
    let mut pd=0;
    while temp<remaining.len() {
        let c=remaining.as_bytes()[temp];
        if c==b'(' { pd+=1; } else if c==b')' { if pd>0 { pd-=1; } }
        else if c==b'{' && pd==0 { sig_end=Some(temp); brace_pos=Some(temp); break; }
        else if c==b';' && pd==0 { sig_end=Some(temp); break; }
        temp+=1;
    }
    let sig_end_idx = sig_end.unwrap_or(remaining.len());
    let modifiers_str = remaining[idx..sig_end_idx].to_string();
    let mutability = extract_mutability(&modifiers_str);
    let is_virtual = modifiers_str.contains("virtual");
    let overrides = extract_overrides(&modifiers_str);
    let mut final_idx = start + sig_end_idx;
    if let Some(bp)=brace_pos {
        let mut depth=1;
        let mut p=start+bp+1;
        while p<body.len() && depth>0 {
            let c=body.as_bytes()[p];
            if c==b'{' { depth+=1; } else if c==b'}' { depth-=1; }
            p+=1;
        }
        final_idx=p;
    } else {
        if final_idx<body.len() && body.as_bytes()[final_idx]==b';' { final_idx+=1; }
    }
    let fb = FallbackInfo { mutability, is_virtual, overrides };
    Some((fb, final_idx))
}

fn parse_receive(body: &str, start: usize) -> Option<(ReceiveInfo, usize)> {
    let remaining = &body[start..];
    let kw_len = "receive".len();
    let mut idx=kw_len;
    while idx<remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    if idx<remaining.len() && remaining.as_bytes()[idx]==b'(' {
        let mut depth=1;
        let mut j=idx+1;
        while j<remaining.len() && depth>0 {
            let c=remaining.as_bytes()[j];
            if c==b'(' { depth+=1; } else if c==b')' { depth-=1; }
            j+=1;
        }
        idx=j;
    }
    while idx<remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    let mut sig_end=None;
    let mut brace_pos=None;
    let mut temp=idx;
    let mut pd=0;
    while temp<remaining.len() {
        let c=remaining.as_bytes()[temp];
        if c==b'(' { pd+=1; } else if c==b')' { if pd>0 { pd-=1; } }
        else if c==b'{' && pd==0 { sig_end=Some(temp); brace_pos=Some(temp); break; }
        else if c==b';' && pd==0 { sig_end=Some(temp); break; }
        temp+=1;
    }
    let sig_end_idx = sig_end.unwrap_or(remaining.len());
    let modifiers_str = remaining[idx..sig_end_idx].to_string();
    let is_virtual = modifiers_str.contains("virtual");
    let overrides = extract_overrides(&modifiers_str);
    let mut final_idx = start + sig_end_idx;
    if let Some(bp)=brace_pos {
        let mut depth=1;
        let mut p=start+bp+1;
        while p<body.len() && depth>0 {
            let c=body.as_bytes()[p];
            if c==b'{' { depth+=1; } else if c==b'}' { depth-=1; }
            p+=1;
        }
        final_idx=p;
    } else {
        if final_idx<body.len() && body.as_bytes()[final_idx]==b';' { final_idx+=1; }
    }
    let rcv = ReceiveInfo { is_virtual, overrides };
    Some((rcv, final_idx))
}

fn parse_event(body: &str, start: usize) -> Option<(EventInfo, usize)> {
    let remaining = &body[start..];
    let kw_len = "event".len();
    let mut idx=kw_len;
    while idx<remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    let name_start=idx;
    while idx<remaining.len() && (remaining.as_bytes()[idx].is_ascii_alphanumeric() || remaining.as_bytes()[idx]==b'_') { idx+=1; }
    let name = remaining[name_start..idx].to_string();
    while idx<remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    if idx>=remaining.len() || remaining.as_bytes()[idx]!=b'(' { return None; }
    let params_start=idx+1;
    let mut depth=1;
    let mut j=params_start;
    while j<remaining.len() && depth>0 {
        let c=remaining.as_bytes()[j];
        if c==b'(' { depth+=1; } else if c==b')' { depth-=1; }
        j+=1;
    }
    let params_str = remaining[params_start..j-1].to_string();
    // After params, look for anonymous and ';'
    let mut k=j;
    while k<remaining.len() && remaining.as_bytes()[k].is_ascii_whitespace() { k+=1; }
    let mut anonymous=false;
    if k+9<=remaining.len() && remaining[k..].starts_with("anonymous") {
        anonymous=true;
        k+=9;
    }
    while k<remaining.len() && remaining.as_bytes()[k]!=b';' { k+=1; }
    let final_idx = if k<remaining.len() { start + k +1 } else { start + remaining.len() };
    let params = parse_event_params(&params_str);
    let ev = EventInfo { name, params, anonymous };
    Some((ev, final_idx))
}

fn parse_error(body: &str, start: usize) -> Option<(ErrorInfo, usize)> {
    let remaining = &body[start..];
    let kw_len = "error".len();
    let mut idx=kw_len;
    while idx<remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    let name_start=idx;
    while idx<remaining.len() && (remaining.as_bytes()[idx].is_ascii_alphanumeric() || remaining.as_bytes()[idx]==b'_') { idx+=1; }
    let name = remaining[name_start..idx].to_string();
    while idx<remaining.len() && remaining.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    if idx>=remaining.len() || remaining.as_bytes()[idx]!=b'(' { return None; }
    let params_start=idx+1;
    let mut depth=1;
    let mut j=params_start;
    while j<remaining.len() && depth>0 {
        let c=remaining.as_bytes()[j];
        if c==b'(' { depth+=1; } else if c==b')' { depth-=1; }
        j+=1;
    }
    let params_str = remaining[params_start..j-1].to_string();
    let mut k=j;
    while k<remaining.len() && remaining.as_bytes()[k]!=b';' { k+=1; }
    let final_idx = if k<remaining.len() { start + k +1 } else { start + remaining.len() };
    let params = parse_params(&params_str);
    let err = ErrorInfo { name, params };
    Some((err, final_idx))
}

fn parse_state_var(line: &str) -> Option<StateVarInfo> {
    let line = line.trim();
    if !line.ends_with(';') { return None; }
    // Skip if contains '(' and ')'? State var shouldn't have parens unless mapping
    // But mapping has parens
    // Check if line contains "function" etc already handled
    // Remove ';'
    let without_semi = line[..line.len()-1].trim();
    if without_semi.is_empty() { return None; }
    // Split by '=' to remove initializer
    let left = if let Some(eq_pos) = without_semi.find('=') {
        without_semi[..eq_pos].trim()
    } else {
        without_semi
    };
    // Find last identifier as name
    // The name is last word that is identifier
    // Use regex to find word at end
    let mut name = None;
    let mut name_pos = None;
    // Scan from end backwards to find identifier
    let mut i = left.len();
    while i>0 {
        i-=1;
        let c = left.as_bytes()[i];
        if c.is_ascii_alphanumeric() || c==b'_' {
            // continue
        } else if c.is_ascii_whitespace() {
            // start of name?
            // Find name from i+1 to end skipping whitespace
            let mut j=i+1;
            while j<left.len() && left.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            let start=j;
            let mut end=start;
            while end<left.len() && (left.as_bytes()[end].is_ascii_alphanumeric() || left.as_bytes()[end]==b'_') { end+=1; }
            if start<end {
                name = Some(left[start..end].to_string());
                name_pos = Some(start);
                break;
            }
        }
    }
    if name.is_none() {
        // If no space found, maybe whole left is name? Unlikely
        // Try to find last word
        let tokens: Vec<&str> = left.split_whitespace().collect();
        if tokens.is_empty() { return None; }
        let last = tokens.last().unwrap();
        if last.chars().all(|c| c.is_alphanumeric() || c=='_') {
            name = Some(last.to_string());
            // Find pos
            if let Some(pos) = left.rfind(last) {
                name_pos = Some(pos);
            }
        }
    }
    let var_name = name?;
    let pos = name_pos?;
    let type_and_vis = left[..pos].trim().to_string();
    if type_and_vis.is_empty() { return None; }

    // Check visibility
    let mut visibility = "internal".to_string();
    let mut is_constant = false;
    let lower = type_and_vis.to_lowercase();
    if lower.contains("public") {
        visibility = "public".to_string();
    } else if lower.contains("private") {
        visibility = "private".to_string();
    } else if lower.contains("internal") {
        visibility = "internal".to_string();
    } else if lower.contains("external") {
        visibility = "external".to_string();
    }
    if lower.contains("constant") || lower.contains("immutable") {
        is_constant = true;
    }

    // Extract type string: remove visibility and other keywords
    let mut type_str = type_and_vis.clone();
    // Remove keywords
    let keywords = [" public", " private", " internal", " external", " constant", " immutable", " virtual", " override", " transient", " payable"];
    // Also handle "override" with parens: remove " override(...)"? Simple remove "override"
    for kw in keywords.iter() {
        type_str = type_str.replace(kw, "");
    }
    // Remove "override" alone
    // Use regex for override(...)
    // Simplify: remove "override" substring
    type_str = type_str.replace("override", "");
    // Remove extra spaces, but keep mapping structure
    // Clean up multiple spaces
    type_str = type_str.split_whitespace().collect::<Vec<_>>().join(" ");
    // Special handling: "address payable" should keep "address payable" as type
    // Our removal removed " payable" as part of keywords, so "address payable" became "address". We need to restore if original contained "address payable"
    if lower.contains("address payable") {
        // If type_str contains "address" but not "payable", add payable if original had it
        if !type_str.contains("payable") && type_str.contains("address") {
            type_str = type_str.replace("address", "address payable");
        }
    }
    let type_str = type_str.trim().to_string();
    if type_str.is_empty() { return None; }

    Some(StateVarInfo { name: var_name, type_str, visibility, is_constant })
}

fn extract_visibility(s: &str) -> Option<String> {
    // Find visibility keywords
    for vis in ["public", "external", "internal", "private"] {
        if s.contains(vis) {
            return Some(vis.to_string());
        }
    }
    None
}

fn extract_mutability(s: &str) -> String {
    if s.contains("payable") {
        "payable".to_string()
    } else if s.contains("view") {
        "view".to_string()
    } else if s.contains("pure") {
        "pure".to_string()
    } else {
        "nonpayable".to_string()
    }
}

fn extract_overrides(s: &str) -> Vec<String> {
    // Look for override keyword
    let mut overrides = Vec::new();
    if let Some(pos) = s.find("override") {
        let after = &s[pos+"override".len()..];
        if let Some(lparen) = after.find('(') {
            if let Some(rparen) = after.find(')') {
                let inner = &after[lparen+1..rparen];
                for part in inner.split(',') {
                    overrides.push(part.trim().to_string());
                }
            }
        }
    }
    overrides
}

fn extract_returns(s: &str) -> String {
    if let Some(pos) = s.find("returns") {
        let after = &s[pos+"returns".len()..];
        // Find '('
        if let Some(lparen) = after.find('(') {
            let mut depth = 1;
            let mut j = lparen+1;
            let bytes = after.as_bytes();
            while j < after.len() && depth>0 {
                if bytes[j]==b'(' { depth+=1; }
                else if bytes[j]==b')' { depth-=1; }
                j+=1;
            }
            if depth==0 {
                return after[lparen+1..j-1].to_string();
            }
        }
    }
    String::new()
}

fn parse_params(s: &str) -> Vec<Param> {
    let mut params = Vec::new();
    if s.trim().is_empty() {
        return params;
    }
    // Split by ',' but respect parentheses (for mapping)
    let mut current = String::new();
    let mut paren_depth = 0;
    for c in s.chars() {
        if c=='(' { paren_depth+=1; current.push(c); }
        else if c==')' { paren_depth-=1; current.push(c); }
        else if c==',' && paren_depth==0 {
            // End of param
            let p = current.trim().to_string();
            if !p.is_empty() {
                if let Some(param) = parse_single_param(&p) {
                    params.push(param);
                }
            }
            current.clear();
        } else {
            current.push(c);
        }
    }
    if !current.trim().is_empty() {
        if let Some(param) = parse_single_param(current.trim()) {
            params.push(param);
        }
    }
    params
}

fn parse_single_param(s: &str) -> Option<Param> {
    let s = s.trim();
    if s.is_empty() { return None; }
    // Check for indexed keyword (for events)
    let mut indexed = false;
    let mut working = s.to_string();
    if working.contains(" indexed ") || working.starts_with("indexed ") || working.ends_with(" indexed") || working=="indexed" {
        // For event params, "uint indexed a"
        // We'll detect
        if working.contains("indexed") {
            indexed = true;
            working = working.replace("indexed", "").trim().to_string();
            // Clean double spaces
            working = working.split_whitespace().collect::<Vec<_>>().join(" ");
        }
    }
    // Now working is like "uint256 _value" or "string memory s" or "S memory s"
    // Extract name as last identifier if present
    // We need to handle data location keywords: memory, storage, calldata

    let tokens: Vec<&str> = working.split_whitespace().collect();
    if tokens.is_empty() { return None; }

    // Data locations
    let data_locations = ["memory", "storage", "calldata"];
    // If last token is identifier and not a data location and not a type keyword, it's name
    // Type keywords set includes elementary types, but also user-defined
    // So we assume if there are at least 2 tokens, last token could be name if it doesn't contain '[' or '(' and is not a data location
    let mut name = "".to_string();
    let mut type_tokens = tokens.clone();

    if tokens.len()>=2 {
        let last = tokens.last().unwrap();
        // If last is data location, then second last might be name? Actually pattern is type [data_location] [name]
        // Example: "string memory s" tokens ["string","memory","s"] -> name "s", type "string", data location memory
        // "uint256[] memory arr" -> ["uint256[]","memory","arr"] -> name arr, type uint256[]
        // "uint256 _value" -> ["uint256","_value"] -> name _value, type uint256
        // "mapping(address => uint256) storage m" -> tokens ["mapping(address","=>","uint256)","storage","m"] -> this is broken because mapping contains spaces

        // For mapping case, our split by whitespace breaks it. So we need better.

        // For now, handle mapping separately: if working contains "mapping", use different logic.

        if working.contains("mapping") {
            // Mapping type is more complex, name is last identifier after space
            // Find last space that separates name
            if let Some(last_space) = working.rfind(' ') {
                let potential_name = working[last_space+1..].trim();
                // Check if potential_name is identifier and not data location
                if !data_locations.contains(&potential_name) && potential_name.chars().all(|c| c.is_alphanumeric() || c=='_') {
                    // Check if before last_space there is data location
                    let before = working[..last_space].trim();
                    let before_tokens: Vec<&str> = before.split_whitespace().collect();
                    if let Some(last_before) = before_tokens.last() {
                        if data_locations.contains(last_before) {
                            // Name is potential_name, type is before without last token
                            let type_part = before[..before.rfind(last_before).unwrap_or(0)].trim().to_string();
                            return Some(Param { name: potential_name.to_string(), type_str: type_part, indexed });
                        } else {
                            // No data location, type is before
                            return Some(Param { name: potential_name.to_string(), type_str: before.to_string(), indexed });
                        }
                    }
                }
            }
            // If no name found, whole is type
            return Some(Param { name: "".to_string(), type_str: working.clone(), indexed });
        }

        // Not mapping
        let last = tokens.last().unwrap().to_string();
        if data_locations.contains(&last.as_str()) {
            // Last is data location, no name
            // Type is all tokens except last (if last is data location)
            // But there could be name before data location? Actually data location comes before name, so if last is data location, name is missing
            let type_part = tokens[..tokens.len()-1].join(" ");
            return Some(Param { name: "".to_string(), type_str: type_part, indexed });
        } else if last.contains('[') || last.contains(']') || last.contains('(') || last.contains(')') {
            // Last token looks like type (contains brackets), so no name
            return Some(Param { name: "".to_string(), type_str: working.clone(), indexed });
        } else {
            // Check if second last is data location
            if tokens.len()>=3 && data_locations.contains(&tokens[tokens.len()-2]) {
                // pattern type data_location name
                let name = tokens[tokens.len()-1].to_string();
                let type_part = tokens[..tokens.len()-2].join(" ");
                return Some(Param { name, type_str: type_part, indexed });
            } else if tokens.len()>=2 {
                // Check if last token is identifier (not type keyword) -> treat as name
                // We need list of elementary type keywords to avoid misclassifying type as name
                let elementary = ["bool","string","bytes","address","uint","int","uint8","uint16","uint32","uint64","uint128","uint256","int8","int16","int32","int64","int128","int256","bytes1","bytes2","bytes3","bytes4","bytes5","bytes6","bytes7","bytes8","bytes9","bytes10","bytes11","bytes12","bytes13","bytes14","bytes15","bytes16","bytes17","bytes18","bytes19","bytes20","bytes21","bytes22","bytes23","bytes24","bytes25","bytes26","bytes27","bytes28","bytes29","bytes30","bytes31","bytes32"];
                let last_lower = last.to_lowercase();
                // If last token is elementary type or contains elementary, it's type not name
                let is_type = elementary.iter().any(|t| last_lower == *t || last_lower.starts_with(&format!("{}[", t)) || last_lower.starts_with(&format!("{} ", t)));
                if !is_type {
                    // Treat as name
                    let name = last.clone();
                    let type_part = tokens[..tokens.len()-1].join(" ");
                    return Some(Param { name, type_str: type_part, indexed });
                }
            }
        }
    }
    // Fallback: whole string is type, no name
    Some(Param { name: "".to_string(), type_str: working.clone(), indexed })
}

fn parse_event_params(s: &str) -> Vec<Param> {
    parse_params(s)
}

// ABI generation helpers

#[derive(Debug, Clone)]
struct AbiParam {
    name: String,
    type_: String,
    internal_type: String,
    indexed: Option<bool>,
    components: Option<Vec<AbiParam>>,
}

fn solidity_type_to_abi(type_str: &str, contract_name: &str, structs: &HashMap<String, StructInfo>, enums: &HashMap<String, EnumInfo>) -> AbiParam {
    // This is simplified
    let trimmed = type_str.trim();
    // Handle mapping? Mapping not allowed in ABI for function params, but for getter we handle elsewhere
    // For now, if mapping, return as is? But should not happen for function params.

    // Handle arrays: recursively
    // Find array suffix
    let (base_type, suffixes) = extract_array_suffix(trimmed);

    // base_type may still be mapping or other
    if base_type.starts_with("mapping") {
        // For mapping in function param (should be internal), we treat type as mapping? But ABI doesn't support mapping param, but we can still handle as string
        // For simplicity, return mapping as is
        return AbiParam {
            name: "".to_string(),
            type_: base_type.clone() + &suffixes.join(""),
            internal_type: base_type.clone() + &suffixes.join(""),
            indexed: None,
            components: None,
        };
    }

    // Check if base_type is struct
    if let Some(struct_info) = structs.get(&base_type) {
        // struct -> tuple
        let mut components = Vec::new();
        for (member_name, member_type) in &struct_info.members {
            let comp_abi = solidity_type_to_abi(member_type, contract_name, structs, enums);
            let mut comp = comp_abi;
            comp.name = member_name.clone();
            components.push(comp);
        }
        let internal = format!("struct {}.{}", contract_name, base_type);
        let mut type_ = "tuple".to_string();
        // Append suffixes
        for suf in &suffixes {
            type_ += suf;
        }
        let mut internal_type = internal;
        for suf in &suffixes {
            internal_type += suf;
        }
        return AbiParam {
            name: "".to_string(),
            type_,
            internal_type,
            indexed: None,
            components: Some(components),
        };
    }

    // Check enum
    if let Some(_enum_info) = enums.get(&base_type) {
        let mut type_ = "uint8".to_string();
        for suf in &suffixes {
            type_ += suf;
        }
        let mut internal_type = format!("enum {}.{}", contract_name, base_type);
        for suf in &suffixes {
            internal_type += suf;
        }
        return AbiParam {
            name: "".to_string(),
            type_,
            internal_type,
            indexed: None,
            components: None,
        };
    }

    // Elementary types
    let (canonical, internal) = canonicalize_elementary(&base_type);

    let mut type_ = canonical;
    let mut internal_type = internal;
    for suf in &suffixes {
        type_ += suf;
        internal_type += suf;
    }

    AbiParam {
        name: "".to_string(),
        type_,
        internal_type,
        indexed: None,
        components: None,
    }
}

fn extract_array_suffix(type_str: &str) -> (String, Vec<String>) {
    let mut s = type_str.trim().to_string();
    let mut suffixes = Vec::new();
    loop {
        if s.ends_with(']') {
            if let Some(lbrace) = s.rfind('[') {
                let suffix = s[lbrace..].to_string();
                suffixes.push(suffix);
                s = s[..lbrace].trim().to_string();
            } else {
                break;
            }
        } else {
            break;
        }
    }
    suffixes.reverse(); // Need to keep order as original: for "uint[][3]", suffixes should be ["[]","[3]"]? Actually "uint[][3]" means array[3] of array[] of uint? The suffix order matters. Our extraction from end gives ["[3]","[]"] reversed to ["[]","[3]"]? Let's think: "uint[][3]" string ends with "]", find last "[", get "[3]", s becomes "uint[]", then next iteration gets "[]", s becomes "uint". suffixes collected: first "[3]", then "[]", list ["[3]","[]"], reverse -> ["[]","[3]"] which matches original order "[]", "[3]"? Original "uint[][3]" has "[]" then "[3]" reading left to right? Actually type "uint[][3]" means: base uint, then [] then [3]? Usually parsing: "uint[][3]" is array of 3 of dynamic arrays? The suffixes left to right are [] then [3]. So ["[]","[3]"] is left to right. Our method gives [] then [3] after reverse? We collected [3] first, then [], list ["[3]","[]"], reverse ["[]","[3]"] => matches left to right. Good.
    (s, suffixes)
}

fn canonicalize_elementary(type_str: &str) -> (String, String) {
    let t = type_str.trim();
    match t {
        "uint" => ("uint256".to_string(), "uint256".to_string()),
        "int" => ("int256".to_string(), "int256".to_string()),
        "address payable" => ("address".to_string(), "address payable".to_string()),
        "address" => ("address".to_string(), "address".to_string()),
        "bool" => ("bool".to_string(), "bool".to_string()),
        "string" => ("string".to_string(), "string".to_string()),
        "bytes" => ("bytes".to_string(), "bytes".to_string()),
        _ => {
            if t.starts_with("uint") {
                // uint8..uint256
                (t.to_string(), t.to_string())
            } else if t.starts_with("int") {
                (t.to_string(), t.to_string())
            } else if t.starts_with("bytes") {
                (t.to_string(), t.to_string())
            } else {
                // Unknown, maybe user-defined, treat as is (for simplicity)
                (t.to_string(), t.to_string())
            }
        }
    }
}

