            base_lins.push(lin);
        }
        let mut lists = base_lins.clone();
        let mut direct_rev = direct_bases.clone();
        direct_rev.reverse();
        lists.push(direct_rev);
        let merged = c3_merge(lists);
        let mut result = vec![name.to_string()];
        result.extend(merged);
