            let c_info = contract_db.get(full_name).unwrap(); // need struct/enum maps from appropriate contract? Use contract where func defined? We have contract_short, but need to find which contract in lin has this func and its structs/enums
            // Find the contract that defines this func by searching lin
            let mut defining_contract: Option<&ContractInfo> = None;
            for lin_name in &lin {
                if let Some(c) = contract_db.get(lin_name) {
                    if c.functions.iter().any(|f| f.name==func.name && f.params.len()==func.params.len()) {
                        // Rough match
                        defining_contract = Some(c);
                        break;
                    }
                }
            }
            let def_c = defining_contract.unwrap_or(contract_db.get(full_name).unwrap());
            let mut inputs = Vec::new();
            for p in &func.params {
                let abi_p = solidity_type_to_abi(&p.type_str, &def_c.name, &def_c.structs, &def_c.enums);
                let mut obj = json!({
                    "name": p.name,
                    "type": abi_p.type_,
                    "internalType": abi_p.internal_type
                });
                if let Some(comps) = abi_p.components {
                    obj["components"] = json!(comps.iter().map(|c| json!({
                        "name": c.name,
                        "type": c.type_,
                        "internalType": c.internal_type
                    })).collect::<Vec<_>>());
                }
                inputs.push(obj);
            }
            let mut outputs = Vec::new();
            for p in &func.returns {
                let abi_p = solidity_type_to_abi(&p.type_str, &def_c.name, &def_c.structs, &def_c.enums);
                let mut obj = json!({
                    "name": p.name,
                    "type": abi_p.type_,
                    "internalType": abi_p.internal_type
                });
                if let Some(comps) = abi_p.components {
                    obj["components"] = json!(comps.iter().map(|c| json!({
                        "name": c.name,
                        "type": c.type_,
                        "internalType": c.internal_type
                    })).collect::<Vec<_>>());
                }
                outputs.push(obj);
            }
            let func_abi = json!({
                "type": "function",
                "name": func.name,
                "inputs": inputs,
                "outputs": outputs,
                "stateMutability": func.mutability
            });
            func_abi_items.push(func_abi);
        }

        // Now combine all func abis (getters + regular) and sort by name stable? Our regular_funcs already sorted, getters also need sorting? Our all_public_vars order is lin order (derived first). After collecting, we have func_abi_items containing getters first (in lin order) then regular funcs sorted. But we need to sort all funcs together by name alphabetical, stable for same name.

        // For simplicity, we will collect all func abis (getters + regular) into one vec and then sort by name alphabetical stable.

        // We have func_abi_items containing getters then regular sorted, but not yet sorted together.

        // Let's sort:

        func_abi_items.sort_by(|a,b| {
            let name_a = a["name"].as_str().unwrap_or("");
            let name_b = b["name"].as_str().unwrap_or("");
            name_a.cmp(name_b)
        });

        // Now final abi_items = ctor (if any) + errors sorted + events sorted + fallback + funcs sorted + receive

        let mut final_abi = Vec::new();
        if let Some(ctor_abi) = abi_items.iter().find(|v| v["type"]=="constructor") {
            final_abi.push(ctor_abi.clone());
        }
        for item in abi_items.iter().filter(|v| v["type"]=="error") {
            final_abi.push(item.clone());
        }
        // errors already sorted
        // events
        let mut event_items: Vec<_> = abi_items.iter().filter(|v| v["type"]=="event").cloned().collect();
        event_items.sort_by(|a,b| a["name"].as_str().cmp(&b["name"].as_str()));
        for ev in event_items {
            final_abi.push(ev);
        }
        if let Some(fb) = abi_items.iter().find(|v| v["type"]=="fallback") {
            final_abi.push(fb.clone());
        }
        for func in func_abi_items {
            final_abi.push(func);
        }
        if let Some(rcv) = abi_items.iter().find(|v| v["type"]=="receive") {
            final_abi.push(rcv.clone());
        }

        // Now we have final_abi for this contract

        // Determine output file path for contract key
        let file_path_for_key = {
            let file = full_name.split(':').next().unwrap_or("");
            if file == "<stdin>" {
                "<stdin>".to_string()
            } else {
                // If base_path set, try to make relative
                if let Some(base) = &cli.base_path {
                    let abs_file = Path::new(file).canonicalize().unwrap_or(PathBuf::from(file));
                    let abs_base = base.canonicalize().unwrap_or(base.clone());
                    if abs_file.starts_with(&abs_base) {
                        abs_file.strip_prefix(&abs_base).unwrap().to_string_lossy().to_string()
                    } else {
                        file.to_string()
                    }
                } else {
                    file.to_string()
                }
            }
        };
        let contract_key = format!("{}:{}", file_path_for_key, contract.name);

        let mut contract_entry = json!({});

        if emit_kinds.contains(&"abi".to_string()) {
            contract_entry["abi"] = json!(final_abi);
        }
        if emit_kinds.contains(&"hashes".to_string()) {
            // Generate hashes from func_abi_items (only functions)
            let mut hashes_map = BTreeMap::new();
            for func_abi in &final_abi {
                if func_abi["type"]=="function" {
                    let name = func_abi["name"].as_str().unwrap_or("");
                    let inputs = func_abi["inputs"].as_array().unwrap();
                    let mut canonical_types = Vec::new();
                    for inp in inputs {
                        // For canonical signature, need type string without internalType, but with tuple etc.
                        // For tuple, canonical is tuple of components? Actually for struct param, canonical signature uses "(uint256,string)" etc? We have type "tuple" with components, but for signature we need to expand tuple into its canonical form: e.g., "f((uint256),uint256[])" etc. So we need to generate canonical signature from AbiParam.

                        // For AbiParam that is tuple, its canonical type for signature is "(" + comma of its components' canonical types + ")" plus suffixes? Actually for struct param, the abi type is tuple, but signature uses tuple representation: "(uint256)" etc.

                        // So we need function to generate canonical type string for signature from AbiParam.

                        // Let's implement helper that takes AbiParam and returns canonical type string for signature.

                        // For now, we will use the "type" field, which for tuple is "tuple" not "(...)". So we need to convert.

                        // We have components, so we can generate "(type1,type2,...)" for tuple.

                        // We'll write function abi_param_to_canonical_signature_type

                        fn abi_to_canonical(p: &serde_json::Value) -> String {
                            let t = p["type"].as_str().unwrap_or("");
                            if t == "tuple" {
                                if let Some(comps) = p.get("components") {
                                    if let Some(arr) = comps.as_array() {
                                        let inner: Vec<String> = arr.iter().map(|c| abi_to_canonical(c)).collect();
                                        format!("({})", inner.join(","))
                                    } else {
                                        "()".to_string()
                                    }
                                } else {
                                    "()".to_string()
                                }
                            } else {
                                t.to_string()
                            }
                        }

                        // But note: for array of tuple, type is "tuple[]"? How to handle suffix? In ABI, type "tuple[]" with components? For signature, array of tuple would be "(uint256)[]" etc. Our abi_to_canonical currently returns "tuple" not handling array suffix. Need to handle array suffix: type "uint256[]" -> canonical "uint256[]", but for tuple array "tuple[]" -> should be "(uint256)[]"? Actually type "tuple[]" with components should be "(uint256)[]" ? Let's see earlier example: f((uint256),uint256[]) had tuple and array. So for tuple array, we need to preserve suffix.

                        // We'll handle by checking if type ends with "[]", "[N]" etc and base is tuple.

                        // For simplicity, if type starts with "tuple" and has suffix, we generate "(" + inner + ")" + suffix.

                        // Let's implement more robust:

                        fn canonical_from_abi_value(v: &serde_json::Value) -> String {
                            let type_str = v["type"].as_str().unwrap_or("");
                            if type_str.starts_with("tuple") {
                                let suffix = &type_str["tuple".len()..];
                                let comps = v.get("components");
                                let inner = if let Some(comps) = comps {
                                    if let Some(arr) = comps.as_array() {
                                        arr.iter().map(|c| canonical_from_abi_value(c)).collect::<Vec<_>>().join(",")
                                    } else {
                                        "".to_string()
                                    }
                                } else {
                                    "".to_string()
                                };
                                format!("({}){}", inner, suffix)
                            } else {
                                type_str.to_string()
                            }
                        }

                        let ct = canonical_from_abi_value(inp);
                        canonical_types.push(ct);
                    }
                    let sig = format!("{}({})", name, canonical_types.join(","));
                    let sel = selector(&sig);
                    hashes_map.insert(sig, sel);
                }
            }
            // Sort hashes by signature alphabetical (BTreeMap does)
            contract_entry["hashes"] = json!(hashes_map);
        }

        contracts_output.insert(contract_key, contract_entry);
    }

    // Build final JSON
    let final_json = json!({
        "contracts": contracts_output,
        "version": "0.1.8"
    });

    // Output handling: if out_dir set, write to combined.json, else stdout
    if let Some(out_dir_path) = cli.out_dir {
        // Check if out_dir exists and is dir
        if !out_dir_path.exists() {
            eprintln!("error: failed to write to output: No such file or directory (os error 2)\n\nerror: aborting due to 1 previous error\n");
            std::process::exit(1);
        }
        if !out_dir_path.is_dir() {
            eprintln!("error: failed to write to output: Not a directory (os error 20)\n\nerror: aborting due to 1 previous error\n");
            std::process::exit(1);
        }
        let combined_path = out_dir_path.join("combined.json");
        let json_str = if cli.pretty_json {
            serde_json::to_string_pretty(&final_json).unwrap()
        } else {
            final_json.to_string()
        };
        if let Err(e) = fs::write(combined_path, json_str) {
            eprintln!("error: failed to write to output: {} (os error {})\n\nerror: aborting due to 1 previous error\n", e, e.raw_os_error().unwrap_or(0));
            std::process::exit(1);
        }
    } else {
        let json_str = if cli.pretty_json {
            serde_json::to_string_pretty(&final_json).unwrap()
        } else {
            final_json.to_string()
        };
        println!("{}", json_str);
    }
}

fn generate_getter_inputs_outputs(sv: &StateVarInfo, structs: &HashMap<String, StructInfo>, enums: &HashMap<String, EnumInfo>, contract_name: &str) -> (Vec<AbiParam>, Vec<AbiParam>) {
    // Parse sv.type_str which may be mapping, array, etc.
    // We need to peel mapping keys and array indices

    let mut inputs = Vec::new();
    let mut current_type_str = sv.type_str.clone();

    // Peel mappings
    loop {
        let trimmed = current_type_str.trim();
        if trimmed.starts_with("mapping") {
            // Extract key and value
            // mapping(key => value)
            if let Some(start) = trimmed.find('(') {
                if let Some(end) = trimmed.rfind(')') {
                    let inner = &trimmed[start+1..end];
                    // Find "=>"
                    if let Some(arrow) = inner.find("=>") {
                        let key_type = inner[..arrow].trim().to_string();
                        let value_type = inner[arrow+2..].trim().to_string();
                        // Key type to abi
                        let key_abi = solidity_type_to_abi(&key_type, contract_name, structs, enums);
                        inputs.push(key_abi);
                        current_type_str = value_type;
                        continue;
                    }
                }
            }
            break;
        } else {
            break;
        }
    }

    // Peel arrays
    loop {
        let (base, suffixes) = extract_array_suffix(&current_type_str);
        if !suffixes.is_empty() {
            // For each suffix, add uint256 input
            for _ in &suffixes {
                // For array getter, input is uint256 index
                inputs.push(AbiParam {
                    name: "".to_string(),
                    type_: "uint256".to_string(),
                    internal_type: "uint256".to_string(),
                    indexed: None,
                    components: None,
                });
            }
            current_type_str = base;
        } else {
            break;
        }
    }

    // Now current_type_str is final return type
    // If it's struct, expand its members into outputs
    let abi_param = solidity_type_to_abi(&current_type_str, contract_name, structs, enums);
    let mut outputs = Vec::new();
    if abi_param.type_ == "tuple" {
        // If struct, expand members? According to earlier observation, for top-level struct getter, outputs are its members expanded, not single tuple
        // But for nested struct member, we already handled? Actually for getter of struct type, we should expand its members as outputs (each member as AbiParam)
        if let Some(comps) = abi_param.components {
            // Each component is already AbiParam with name and type
            for comp in comps {
                outputs.push(comp);
            }
        } else {
            outputs.push(abi_param);
        }
    } else {
        // Single output
        let mut out = abi_param;
        out.name = "".to_string(); // getter outputs have empty name? For simple var, name ""? In earlier output for simple getter, name was "" for return? Actually for public var getter, outputs have name "" for simple, but for struct getter with members, names are member names. We already have that.
        outputs.push(out);
    }

    (inputs, outputs)
}
