        .arg(Arg::new("INPUT").value_name("INPUT").num_args(0..).help("Files to compile, or import remappings"))
        .arg(Arg::new("threads").short('j').long("threads").value_name("THREADS").default_value("8").aliases(["jobs"]).help("Number of threads to use. Zero specifies the number of logical cores"))
        .arg(Arg::new("evm-version").long("evm-version").value_name("EVM_VERSION").default_value("prague").value_parser(["homestead","tangerineWhistle","spuriousDragon","byzantium","constantinople","petersburg","istanbul","berlin","london","paris","shanghai","cancun","prague","osaka"]))
        .arg(Arg::new("stop-after").long("stop-after").value_name("STOP_AFTER").value_parser(["parsing","lowering","analysis"]))
        .arg(Arg::new("out-dir").long("out-dir").value_name("OUT_DIR"))
