        .arg(Arg::new("include-path").short('I').long("include-path").value_name("INCLUDE_PATH").action(ArgAction::Append))
        .arg(Arg::new("allow-paths").long("allow-paths").value_name("ALLOW_PATHS").action(ArgAction::Append))
        .arg(Arg::new("color").long("color").value_name("COLOR").default_value("auto").value_parser(["auto","always","never"]))
