fn parse_event_simple(body: &str, start: usize) -> Option<(EventInfo, usize)> {
    let rem=&body[start..];
    let mut idx="event".len();
    while idx<rem.len() && rem.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    let ns=idx;
    while idx<rem.len() && (rem.as_bytes()[idx].is_ascii_alphanumeric() || rem.as_bytes()[idx]==b'_') { idx+=1; }
    let name=rem[ns..idx].to_string();
    while idx<rem.len() && rem.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    if idx>=rem.len() || rem.as_bytes()[idx]!=b'(' { return None; }
    let ps=idx+1;
    let mut depth=1;
    let mut j=ps;
    while j<rem.len() && depth>0 {
        let c=rem.as_bytes()[j];
        if c==b'(' { depth+=1; } else if c==b')' { depth-=1; }
        j+=1;
    }
    let params_str=rem[ps..j-1].to_string();
    let mut k=j;
    while k<rem.len() && rem.as_bytes()[k].is_ascii_whitespace() { k+=1; }
    let mut anonymous=false;
    if k+9<=rem.len() && rem[k..].starts_with("anonymous") {
        anonymous=true;
        k+=9;
    }
    while k<rem.len() && rem.as_bytes()[k]!=b';' { k+=1; }
    let final_idx=if k<rem.len() { start+k+1 } else { start+rem.len() };
    let params=parse_params_simple(&params_str);
    Some((EventInfo { name, params, anonymous }, final_idx))
}

