fn parse_state_var_simple(line: &str) -> Option<StateVarInfo> {
    let line=line.trim();
    if !line.ends_with(';') { return None; }
    let without_semi=line[..line.len()-1].trim();
    let left = if let Some(eq)=without_semi.find('=') { without_semi[..eq].trim() } else { without_semi };
    // Find last identifier as name
    // Split by whitespace, last token is name
    // But type may contain spaces, so find last space
    if let Some(last_space) = left.rfind(|c: char| c.is_whitespace()) {
        let name_candidate = left[last_space+1..].trim();
        if name_candidate.chars().all(|c| c.is_alphanumeric()||c=='_') {
            let type_and_vis = left[..last_space].trim();
            // Determine visibility
            let mut vis = "internal".to_string();
            let lower = type_and_vis.to_lowercase();
            if lower.contains("public") { vis="public".to_string(); }
            else if lower.contains("private") { vis="private".to_string(); }
            else if lower.contains("internal") { vis="internal".to_string(); }
            // Extract type: remove visibility keywords
            let mut type_str = type_and_vis.to_string();
            for kw in [" public", " private", " internal", " external", " constant", " immutable", " virtual", " override", " transient"] {
                type_str = type_str.replace(kw, "");
            }
            type_str = type_str.replace("override", "");
            type_str = type_str.split_whitespace().collect::<Vec<_>>().join(" ");
            if type_str.contains("address") && lower.contains("address payable") {
                if !type_str.contains("payable") {
                    type_str = type_str.replace("address", "address payable");
                }
            }
            let type_str = type_str.trim().to_string();
            if type_str.is_empty() { return None; }
            return Some(StateVarInfo { name: name_candidate.to_string(), type_str, visibility: vis, is_constant: lower.contains("constant")||lower.contains("immutable") });
        }
    }
    None
}

fn parse_params_simple(s: &str) -> Vec<Param> {
    let mut params=Vec::new();
    if s.trim().is_empty() { return params; }
    let mut current=String::new();
    let mut depth=0;
    for c in s.chars() {
        if c=='(' { depth+=1; current.push(c); }
        else if c==')' { depth-=1; current.push(c); }
        else if c==',' && depth==0 {
            if let Some(p)=parse_single_param_simple(current.trim()) {
                params.push(p);
            }
            current.clear();
        } else {
            current.push(c);
        }
    }
    if !current.trim().is_empty() {
        if let Some(p)=parse_single_param_simple(current.trim()) {
            params.push(p);
        }
    }
    params
}

fn parse_single_param_simple(s: &str) -> Option<Param> {
    let s=s.trim();
    if s.is_empty() { return None; }
    let mut indexed=false;
    let mut working=s.to_string();
    if working.contains(" indexed ") || working.starts_with("indexed ") || working.ends_with(" indexed") {
        indexed=true;
        working=working.replace("indexed", "").trim().to_string();
        working=working.split_whitespace().collect::<Vec<_>>().join(" ");
    }
    // Handle mapping separately
    if working.contains("mapping") {
        // Find last space for name
        if let Some(last_space)=working.rfind(' ') {
            let potential_name=working[last_space+1..].trim();
            if potential_name.chars().all(|c| c.is_alphanumeric()||c=='_') && !["memory","storage","calldata","indexed"].contains(&potential_name) {
                let type_part=working[..last_space].trim().to_string();
                // Check if type_part ends with data location
                let type_part_trim=type_part.trim();
                let data_locs=["memory","storage","calldata"];
                let mut final_type=type_part_trim.to_string();
                let mut name=potential_name.to_string();
                // If type_part ends with data location, remove it
                for dl in data_locs {
                    if type_part_trim.ends_with(dl) {
                        // Remove dl
                        final_type=type_part_trim[..type_part_trim.len()-dl.len()].trim().to_string();
                        break;
                    }
                }
                return Some(Param { name, type_str: final_type, indexed });
            }
        }
        return Some(Param { name: "".to_string(), type_str: working.clone(), indexed });
    }
    // Not mapping
    let tokens:Vec<&str>=working.split_whitespace().collect();
    if tokens.is_empty() { return None; }
    let data_locs=["memory","storage","calldata"];
    if tokens.len()>=2 {
        let last=tokens.last().unwrap().to_string();
        if data_locs.contains(&last.as_str()) {
            // No name
            let type_part=tokens[..tokens.len()-1].join(" ");
            return Some(Param { name: "".to_string(), type_str: type_part, indexed });
        } else {
            // Check if second last is data location
            if tokens.len()>=3 && data_locs.contains(&tokens[tokens.len()-2]) {
                let name=tokens[tokens.len()-1].to_string();
                let type_part=tokens[..tokens.len()-2].join(" ");
                return Some(Param { name, type_str: type_part, indexed });
            } else {
                // Last token might be name
                // Check if last token looks like type (contains brackets or is elementary)
                let elementary=["bool","string","bytes","address","uint","int","uint8","uint16","uint32","uint64","uint128","uint256","int8","int16","int32","int64","int128","int256","bytes1","bytes2","bytes3","bytes4","bytes5","bytes6","bytes7","bytes8","bytes9","bytes10","bytes11","bytes12","bytes13","bytes14","bytes15","bytes16","bytes17","bytes18","bytes19","bytes20","bytes21","bytes22","bytes23","bytes24","bytes25","bytes26","bytes27","bytes28","bytes29","bytes30","bytes31","bytes32"];
                let last_lower=last.to_lowercase();
                let mut is_type=false;
                for et in elementary {
                    if last_lower==et || last_lower.starts_with(&format!("{}[", et)) {
                        is_type=true;
                        break;
                    }
                }
                if is_type {
                    return Some(Param { name: "".to_string(), type_str: working.clone(), indexed });
                } else {
                    let name=last.clone();
                    let type_part=tokens[..tokens.len()-1].join(" ");
                    return Some(Param { name, type_str: type_part, indexed });
                }
            }
        }
    }
    Some(Param { name: "".to_string(), type_str: working.clone(), indexed })
}

fn solidity_type_to_abi_simple(type_str: &str) -> (String, String) {
    let t = type_str.trim();
    // Handle arrays
    let (base, suffixes) = extract_array_suffix_simple(t);
    let base_trim = base.trim();
    let (canonical_base, internal_base) = match base_trim {
        "uint" => ("uint256".to_string(), "uint256".to_string()),
        "int" => ("int256".to_string(), "int256".to_string()),
        "address payable" => ("address".to_string(), "address payable".to_string()),
        "address" => ("address".to_string(), "address".to_string()),
        "bool" => ("bool".to_string(), "bool".to_string()),
        "string" => ("string".to_string(), "string".to_string()),
        "bytes" => ("bytes".to_string(), "bytes".to_string()),
        _ => {
            if base_trim.starts_with("uint") || base_trim.starts_with("int") || base_trim.starts_with("bytes") {
                (base_trim.to_string(), base_trim.to_string())
            } else if base_trim.starts_with("mapping") {
                // Mapping shouldn't appear in ABI for function, but for getter we handle elsewhere
                (base_trim.to_string(), base_trim.to_string())
            } else {
                // Assume it's struct or enum or unknown - for simplicity, if it's a single word and not elementary, treat as tuple? But we need to know if struct or enum
                // For our simple version, if it looks like struct (capital letter), treat as tuple with internal struct
                // We'll need more info but we don't have. So we will treat unknown single word as uint8 if it could be enum? For simplicity, if it contains only letters and first char uppercase, treat as tuple? No.

                // For now, check if type is known struct? We don't have struct map here.

                // We'll treat as same as input (for unknown)
                (base_trim.to_string(), base_trim.to_string())
            }
        }
    };
    let mut canonical = canonical_base;
    let mut internal = internal_base;
    for suf in suffixes {
        canonical += &suf;
        internal += &suf;
    }
    (canonical, internal)
}

fn extract_array_suffix_simple(type_str: &str) -> (String, Vec<String>) {
    let mut s = type_str.trim().to_string();
    let mut suffixes = Vec::new();
    loop {
        if s.ends_with(']') {
            if let Some(l) = s.rfind('[') {
                let suf = s[l..].to_string();
                suffixes.push(suf);
                s = s[..l].trim().to_string();
            } else { break; }
        } else { break; }
    }
    suffixes.reverse();
    (s, suffixes)
}

fn generate_getter_simple(sv: &StateVarInfo, c_info: &ContractInfo) -> (Vec<(String,String,String)>, Vec<(String,String,String)>) {
    // Returns (inputs Vec<(name,type,internal)>, outputs Vec<(name,type,internal)>)
    let mut inputs = Vec::new();
    let mut current_type = sv.type_str.clone();

    // Peel mappings
    loop {
        let trimmed = current_type.trim().to_string();
        if trimmed.starts_with("mapping") {
            if let Some(start) = trimmed.find('(') {
                if let Some(end) = trimmed.rfind(')') {
                    let inner = &trimmed[start+1..end];
                    if let Some(arrow) = inner.find("=>") {
                        let key_type = inner[..arrow].trim().to_string();
                        let value_type = inner[arrow+2..].trim().to_string();
                        let key_abi = solidity_type_to_abi_simple(&key_type);
                        inputs.push(("".to_string(), key_abi.0, key_abi.1));
                        current_type = value_type;
                        continue;
                    }
                }
            }
            break;
        } else { break; }
    }

    // Peel arrays
    loop {
        let (base, suffixes) = extract_array_suffix_simple(&current_type);
        if !suffixes.is_empty() {
            for _ in &suffixes {
                inputs.push(("".to_string(), "uint256".to_string(), "uint256".to_string()));
            }
            current_type = base;
        } else { break; }
    }

    // Now final type is return type
    // If it's struct, expand members
    let mut outputs = Vec::new();
    let final_type_trimmed = current_type.trim();
    if let Some(struct_info) = c_info.structs.get(final_type_trimmed) {
        // Expand members
        for (member_name, member_type) in &struct_info.members {
            let abi = solidity_type_to_abi_simple(member_type);
            outputs.push((member_name.clone(), abi.0, abi.1));
        }
    } else {
        // Check if it's struct name with contract prefix?
        // For simplicity, if final_type is known struct in this contract, expand, else single output
        let abi = solidity_type_to_abi_simple(final_type_trimmed);
        if abi.0 == "tuple" {
            // If we treated unknown as tuple? Actually our simple abi returns same as input for unknown, not tuple. So this case won't happen.
            outputs.push(("".to_string(), abi.0, abi.1));
        } else {
            // For simple type, output name ""? For struct expanded, names are member names, we already handled.
            // For public var getter of struct, outputs have member names, which we handled via struct expansion.
            // For simple var, output name "".
            outputs.push(("".to_string(), abi.0, abi.1));
        }
    }

    (inputs, outputs)
}

