fn extract_imports(content: &str) -> Vec<String> {
    let mut imports = Vec::new();
    let mut idx = 0;
    while idx < content.len() {
        if content[idx..].starts_with("import") {
            let prev_ok = if idx==0 { true } else { 
                let prev = content.as_bytes()[idx-1];
                !prev.is_ascii_alphanumeric() && prev != b'_'
            };
            if prev_ok {
                let mut j = idx+6;
                while j < content.len() && content.as_bytes()[j].is_ascii_whitespace() { j+=1; }
                let mut k=j;
                while k < content.len() && k < j+500 {
                    let c = content.as_bytes()[k];
                    if c==b'"' || c==b'\'' {
                        let quote=c;
                        let mut end=k+1;
                        while end<content.len() && content.as_bytes()[end]!=quote { end+=1; }
                        if end<content.len() {
                            let path=&content[k+1..end];
                            imports.push(path.to_string());
                            break;
                        }
                    }
                    if c==b';' { break; }
                    k+=1;
                }
            }
        }
        idx+=1;
    }
    imports
}

fn resolve_import(import_path: &str, current_file: &str, base_path: &Option<PathBuf>, include_paths: &Vec<PathBuf>, remappings: &Vec<Remapping>) -> Result<String, String> {
    let mut path = import_path.to_string();
    let mut sorted_remaps = remappings.clone();
    sorted_remaps.sort_by(|a,b| b.prefix.len().cmp(&a.prefix.len()));
    for remap in &sorted_remaps {
        if let Some(ctx) = &remap.context {
            if !current_file.ends_with(ctx) && current_file != ctx {
                continue;
            }
        }
        if path.starts_with(&remap.prefix) {
            let rest = &path[remap.prefix.len()..];
            let new_path = remap.path.join(rest);
            path = new_path.to_string_lossy().to_string();
            break;
        }
    }
    if Path::new(&path).is_absolute() {
        if Path::new(&path).exists() {
            return Ok(path);
        } else {
            return Err(format!("file {} not found", import_path));
        }
    }
    if path.starts_with("./") || path.starts_with("../") {
        let current_dir = if current_file == "<stdin>" {
            PathBuf::from(".")
        } else {
            Path::new(current_file).parent().map(|p| p.to_path_buf()).unwrap_or(PathBuf::from("."))
        };
        let resolved = current_dir.join(&path);
        let normalized = normalize_path(&resolved);
        if normalized.exists() {
            if let Some(base) = base_path {
                let base_canon = base.canonicalize().unwrap_or(base.clone());
                let res_canon = normalized.canonicalize().unwrap_or(normalized.clone());
                if !res_canon.starts_with(&base_canon) {
                    return Err(format!("file {} not found", import_path));
                }
            }
            return Ok(normalized.to_string_lossy().to_string());
        } else {
            return Err(format!("file {} not found", import_path));
        }
    }
    for inc in include_paths {
        let candidate = inc.join(&path);
        if candidate.exists() {
            return Ok(candidate.to_string_lossy().to_string());
        }
    }
    if let Some(base) = base_path {
        let candidate = base.join(&path);
        if candidate.exists() {
            return Ok(candidate.to_string_lossy().to_string());
        }
    }
    Err(format!("file {} not found", import_path))
}

fn normalize_path(p: &PathBuf) -> PathBuf {
    let mut components = Vec::new();
    for comp in p.components() {
        use std::path::Component;
        match comp {
            Component::ParentDir => { components.pop(); },
            Component::CurDir => {},
            _ => components.push(comp),
        }
    }
    let mut res = PathBuf::new();
    for c in components {
        res.push(c);
    }
    res
}

