fn remove_comments(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    let mut in_single = false;
    let mut in_multi = false;
    let mut in_string = false;
    let mut string_char = '"';
    while let Some(c) = chars.next() {
        if in_single {
            if c == '\n' {
                in_single = false;
                result.push(c);
            }
            continue;
        }
        if in_multi {
            if c == '*' {
                if let Some(&next) = chars.peek() {
                    if next == '/' {
                        chars.next();
                        in_multi = false;
                    }
                }
            }
            continue;
        }
        if in_string {
            result.push(c);
            if c == string_char {
                in_string = false;
            }
            continue;
        }
        if c == '/' {
            if let Some(&next) = chars.peek() {
                if next == '/' {
                    chars.next();
                    in_single = true;
                    continue;
                } else if next == '*' {
                    chars.next();
                    in_multi = true;
                    continue;
                }
            }
            result.push(c);
        } else if c == '"' || c == '\'' {
            in_string = true;
            string_char = c;
            result.push(c);
        } else {
            result.push(c);
        }
    }
    result
}

fn find_keyword(s: &str, start: usize, keywords: &[&str]) -> Option<usize> {
    let mut idx = start;
    while idx < s.len() {
        for kw in keywords {
            if s[idx..].starts_with(kw) {
                if idx>0 {
                    let prev = s.as_bytes()[idx-1];
                    if prev.is_ascii_alphanumeric() || prev == b'_' {
                        continue;
                    }
                }
                let next_idx = idx + kw.len();
                if next_idx < s.len() {
                    let next = s.as_bytes()[next_idx];
                    if next.is_ascii_alphanumeric() || next == b'_' {
                        continue;
                    }
                }
                return Some(idx);
            }
        }
        idx+=1;
    }
    None
}

fn find_next_semicolon(body: &str, start: usize) -> Option<usize> {
    let bytes = body.as_bytes();
    let mut i = start;
    let mut paren_depth = 0;
    let mut brace_depth = 0;
    while i < body.len() {
        let c = bytes[i];
        if c == b'(' { paren_depth+=1; }
        else if c == b')' { if paren_depth>0 { paren_depth-=1; } }
        else if c == b'{' { brace_depth+=1; }
        else if c == b'}' { if brace_depth>0 { brace_depth-=1; } }
        else if c == b';' && paren_depth==0 && brace_depth==0 {
            return Some(i);
        }
        i+=1;
    }
    None
}

fn extract_visibility(s: &str) -> Option<String> {
    for vis in ["public", "external", "internal", "private"] {
        if s.contains(vis) {
            return Some(vis.to_string());
        }
    }
    None
}

fn extract_mutability(s: &str) -> String {
    if s.contains("payable") { "payable".to_string() }
    else if s.contains("view") { "view".to_string() }
    else if s.contains("pure") { "pure".to_string() }
    else { "nonpayable".to_string() }
}

fn extract_overrides(s: &str) -> Vec<String> {
    let mut overrides = Vec::new();
    if let Some(pos) = s.find("override") {
        let after = &s[pos+"override".len()..];
        if let Some(l) = after.find('(') {
            if let Some(r) = after.find(')') {
                let inner = &after[l+1..r];
                for part in inner.split(',') {
                    overrides.push(part.trim().to_string());
                }
            }
        }
    }
    overrides
}

fn extract_returns(s: &str) -> String {
    if let Some(pos) = s.find("returns") {
        let after = &s[pos+"returns".len()..];
        if let Some(l) = after.find('(') {
            let mut depth=1;
            let mut j=l+1;
            let bytes=after.as_bytes();
            while j<after.len() && depth>0 {
                if bytes[j]==b'(' { depth+=1; } else if bytes[j]==b')' { depth-=1; }
                j+=1;
            }
            if depth==0 {
                return after[l+1..j-1].to_string();
            }
        }
    }
    String::new()
}

#[derive(Debug, Clone)]
struct AbiParam {
    name: String,
    type_: String,
    internal_type: String,
    indexed: Option<bool>,
    components: Option<Vec<AbiParam>>,
}

fn solidity_type_to_abi(type_str: &str, contract_name: &str, structs: &HashMap<String, StructInfo>, enums: &HashMap<String, EnumInfo>) -> AbiParam {
    let trimmed = type_str.trim();
    let (base_type, suffixes) = extract_array_suffix(trimmed);
    if base_type.starts_with("mapping") {
        return AbiParam {
            name: "".to_string(),
            type_: base_type.clone() + &suffixes.join(""),
            internal_type: base_type.clone() + &suffixes.join(""),
            indexed: None,
            components: None,
        };
    }
    if let Some(struct_info) = structs.get(&base_type) {
        let mut components = Vec::new();
        for (member_name, member_type) in &struct_info.members {
            let mut comp_abi = solidity_type_to_abi(member_type, contract_name, structs, enums);
            comp_abi.name = member_name.clone();
            components.push(comp_abi);
        }
        let internal = format!("struct {}.{}", contract_name, base_type);
        let mut type_ = "tuple".to_string();
        let mut internal_type = internal;
        for suf in &suffixes {
            type_ += suf;
            internal_type += suf;
        }
        return AbiParam {
            name: "".to_string(),
            type_,
            internal_type,
            indexed: None,
            components: Some(components),
        };
    }
    if let Some(_enum_info) = enums.get(&base_type) {
        let mut type_ = "uint8".to_string();
        let mut internal_type = format!("enum {}.{}", contract_name, base_type);
        for suf in &suffixes {
            type_ += suf;
            internal_type += suf;
        }
        return AbiParam {
            name: "".to_string(),
            type_,
            internal_type,
            indexed: None,
            components: None,
        };
    }
    let (canonical, internal) = canonicalize_elementary(&base_type);
    let mut type_ = canonical;
    let mut internal_type = internal;
    for suf in &suffixes {
        type_ += suf;
        internal_type += suf;
    }
    AbiParam {
        name: "".to_string(),
        type_,
        internal_type,
        indexed: None,
        components: None,
    }
}

fn extract_array_suffix(type_str: &str) -> (String, Vec<String>) {
    let mut s = type_str.trim().to_string();
    let mut suffixes = Vec::new();
    loop {
        if s.ends_with(']') {
            if let Some(l) = s.rfind('[') {
                let suf = s[l..].to_string();
                suffixes.push(suf);
                s = s[..l].trim().to_string();
            } else { break; }
        } else { break; }
    }
    suffixes.reverse();
    (s, suffixes)
}

fn canonicalize_elementary(type_str: &str) -> (String, String) {
    let t = type_str.trim();
    match t {
        "uint" => ("uint256".to_string(), "uint256".to_string()),
        "int" => ("int256".to_string(), "int256".to_string()),
        "address payable" => ("address".to_string(), "address payable".to_string()),
        "address" => ("address".to_string(), "address".to_string()),
        "bool" => ("bool".to_string(), "bool".to_string()),
        "string" => ("string".to_string(), "string".to_string()),
        "bytes" => ("bytes".to_string(), "bytes".to_string()),
        _ => {
            if t.starts_with("uint") || t.starts_with("int") || t.starts_with("bytes") {
                (t.to_string(), t.to_string())
            } else {
                (t.to_string(), t.to_string())
            }
        }
    }
}
