        } else {
            eprintln!("error: no files found\n  │\n  ╰ note: if you wish to use the standard input, please specify `-` explicitly\n\nerror: aborting due to 1 previous error\n");
        }
        std::process::exit(1);
    }

    // Process remappings and files
    let mut remappings: Vec<Remapping> = Vec::new();
    let mut files: Vec<String> = Vec::new();
    for inp in &inputs {
        if inp == "-" {
            files.push("-".to_string());
        } else if inp.contains('=') {
            let p = Path::new(inp);
            if p.exists() {
                files.push(inp.clone());
            } else {
                if let Some(eq_idx) = inp.rfind('=') {
                    let left = &inp[..eq_idx];
                    let path = &inp[eq_idx+1..];
                    if let Some(colon_idx) = left.rfind(':') {
                        let context = &left[..colon_idx];
                        let prefix = &left[colon_idx+1..];
                        remappings.push(Remapping { context: Some(context.to_string()), prefix: prefix.to_string(), path: PathBuf::from(path) });
                    } else {
                        remappings.push(Remapping { context: None, prefix: left.to_string(), path: PathBuf::from(path) });
                    }
                }
            }
        } else {
            files.push(inp.clone());
        }
    }

    let mut source_contents: BTreeMap<String, String> = BTreeMap::new();
    let mut input_file_list: Vec<String> = Vec::new();
    let mut has_error = false;

    for f in &files {
        if f == "-" {
            let mut content = String::new();
            use std::io::Read;
