fn extract_mutability(s: &str) -> String {
    if s.contains("payable") { "payable".to_string() }
    else if s.contains("view") { "view".to_string() }
    else if s.contains("pure") { "pure".to_string() }
    else { "nonpayable".to_string() }
}

fn extract_returns(s: &str) -> String {
    if let Some(pos) = s.find("returns") {
        let after = &s[pos+"returns".len()..];
        if let Some(l) = after.find('(') {
            let mut depth=1;
            let mut j=l+1;
            let bytes=after.as_bytes();
            while j<after.len() && depth>0 {
                if bytes[j]==b'(' { depth+=1; } else if bytes[j]==b')' { depth-=1; }
                j+=1;
            }
            if depth==0 { return after[l+1..j-1].to_string(); }
        }
    }
    String::new()
}

fn parse_params(s: &str) -> Vec<Param> {
    let mut params=Vec::new();
    if s.trim().is_empty() { return params; }
    let mut current=String::new();
    let mut depth=0;
    for c in s.chars() {
        if c=='(' { depth+=1; current.push(c); }
        else if c==')' { depth-=1; current.push(c); }
        else if c==',' && depth==0 {
            if let Some(p)=parse_single_param(current.trim()) { params.push(p); }
            current.clear();
        } else { current.push(c); }
    }
    if !current.trim().is_empty() {
        if let Some(p)=parse_single_param(current.trim()) { params.push(p); }
    }
    params
}

fn parse_single_param(s: &str) -> Option<Param> {
    let s=s.trim();
    if s.is_empty() { return None; }
    let mut indexed=false;
    let mut working=s.to_string();
    if working.contains("indexed") {
        indexed=true;
        working=working.replace("indexed", "").trim().to_string();
        working=working.split_whitespace().collect::<Vec<_>>().join(" ");
    }
    if working.contains("mapping") {
        if let Some(last_space)=working.rfind(' ') {
            let potential_name=working[last_space+1..].trim();
            if potential_name.chars().all(|c| c.is_alphanumeric()||c=='_') && !["memory","storage","calldata"].contains(&potential_name) {
                let type_part=working[..last_space].trim().to_string();
                let mut final_type=type_part.clone();
                for dl in ["memory","storage","calldata"] {
                    if final_type.ends_with(dl) {
                        final_type=final_type[..final_type.len()-dl.len()].trim().to_string();
                        break;
                    }
                }
                return Some(Param { name: potential_name.to_string(), type_str: final_type, indexed });
            }
        }
        return Some(Param { name: "".to_string(), type_str: working.clone(), indexed });
    }
    let tokens:Vec<&str>=working.split_whitespace().collect();
    if tokens.is_empty() { return None; }
    let data_locs=["memory","storage","calldata"];
    if tokens.len()>=2 {
        let last=tokens.last().unwrap().to_string();
        if data_locs.contains(&last.as_str()) {
            let type_part=tokens[..tokens.len()-1].join(" ");
            return Some(Param { name: "".to_string(), type_str: type_part, indexed });
        } else {
            if tokens.len()>=3 && data_locs.contains(&tokens[tokens.len()-2]) {
                let name=tokens[tokens.len()-1].to_string();
                let type_part=tokens[..tokens.len()-2].join(" ");
                return Some(Param { name, type_str: type_part, indexed });
            } else {
                let elementary=["bool","string","bytes","address","uint","int"];
                let last_lower=last.to_lowercase();
                let mut is_type=false;
                for et in elementary {
                    if last_lower==et || last_lower.starts_with(&format!("{}[", et)) { is_type=true; break; }
                }
                if last_lower.starts_with("uint") || last_lower.starts_with("int") || last_lower.starts_with("bytes") {
                    is_type=true;
                }
                if is_type && tokens.len()==1 {
                    return Some(Param { name: "".to_string(), type_str: working.clone(), indexed });
                } else if !is_type {
                    let name=last.clone();
                    let type_part=tokens[..tokens.len()-1].join(" ");
                    if type_part.is_empty() {
                        return Some(Param { name: "".to_string(), type_str: name.clone(), indexed });
                    }
                    return Some(Param { name, type_str: type_part, indexed });
                }
            }
        }
    }
    Some(Param { name: "".to_string(), type_str: working.clone(), indexed })
}

fn solidity_type_to_abi_simple(type_str: &str) -> (String, String) {
    let t = type_str.trim();
    let (base, suffixes) = extract_array_suffix_simple(t);
    let base_trim = base.trim();
    let (canonical_base, internal_base) = match base_trim {
        "uint" => ("uint256".to_string(), "uint256".to_string()),
        "int" => ("int256".to_string(), "int256".to_string()),
        "address payable" => ("address".to_string(), "address payable".to_string()),
        "address" => ("address".to_string(), "address".to_string()),
        "bool" => ("bool".to_string(), "bool".to_string()),
        "string" => ("string".to_string(), "string".to_string()),
        "bytes" => ("bytes".to_string(), "bytes".to_string()),
        _ => {
            if base_trim.starts_with("uint") || base_trim.starts_with("int") || base_trim.starts_with("bytes") {
                (base_trim.to_string(), base_trim.to_string())
            } else {
                (base_trim.to_string(), base_trim.to_string())
            }
        }
    };
    let mut canonical = canonical_base;
    let mut internal = internal_base;
    for suf in suffixes {
        canonical += &suf;
        internal += &suf;
    }
    (canonical, internal)
}

fn extract_array_suffix_simple(type_str: &str) -> (String, Vec<String>) {
    let mut s = type_str.trim().to_string();
    let mut suffixes = Vec::new();
    loop {
        if s.ends_with(']') {
            if let Some(l) = s.rfind('[') {
                let suf = s[l..].to_string();
                suffixes.push(suf);
                s = s[..l].trim().to_string();
            } else { break; }
        } else { break; }
    }
    suffixes.reverse();
    (s, suffixes)
}

fn generate_getter_simple(sv: &StateVarInfo, c_info: &ContractInfo) -> (Vec<(String,String,String)>, Vec<(String,String,String)>) {
    let mut inputs = Vec::new();
    let mut current_type = sv.type_str.clone();
    loop {
        let trimmed = current_type.trim().to_string();
        if trimmed.starts_with("mapping") {
            if let Some(start) = trimmed.find('(') {
                if let Some(end) = trimmed.rfind(')') {
                    let inner = &trimmed[start+1..end];
                    if let Some(arrow) = inner.find("=>") {
                        let key_type = inner[..arrow].trim().to_string();
                        let value_type = inner[arrow+2..].trim().to_string();
                        let key_abi = solidity_type_to_abi_simple(&key_type);
                        inputs.push(("".to_string(), key_abi.0, key_abi.1));
                        current_type = value_type;
                        continue;
                    }
                }
            }
            break;
        } else { break; }
    }
    loop {
        let (base, suffixes) = extract_array_suffix_simple(&current_type);
        if !suffixes.is_empty() {
            for _ in &suffixes {
                inputs.push(("".to_string(), "uint256".to_string(), "uint256".to_string()));
            }
            current_type = base;
        } else { break; }
    }
    let mut outputs = Vec::new();
    let final_type_trimmed = current_type.trim();
    if let Some(struct_info) = c_info.structs.get(final_type_trimmed) {
        for (member_name, member_type) in &struct_info.members {
            let abi = solidity_type_to_abi_simple(member_type);
            outputs.push((member_name.clone(), abi.0, abi.1));
        }
    } else {
        let abi = solidity_type_to_abi_simple(final_type_trimmed);
        outputs.push(("".to_string(), abi.0, abi.1));
    }
    (inputs, outputs)
}

fn parse_contracts_simple(content: &str, _file_path: &str) -> Vec<ContractInfo> {
    let cleaned = remove_comments(content);
    let mut contracts = Vec::new();
    let mut idx = 0;
    while idx < cleaned.len() {
        if let Some(pos) = find_keyword(&cleaned, idx, &["contract", "interface", "library"]) {
            let mut kw_len = 0;
            let mut keyword = "";
            for k in ["contract", "interface", "library"] {
                if cleaned[pos..].starts_with(k) {
                    keyword = k;
                    kw_len = k.len();
                    break;
                }
            }
            if keyword.is_empty() { idx = pos+1; continue; }
            let mut j = pos + kw_len;
            while j < cleaned.len() && cleaned.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            let name_start = j;
            while j < cleaned.len() && (cleaned.as_bytes()[j].is_ascii_alphanumeric() || cleaned.as_bytes()[j]==b'_') { j+=1; }
            let name = cleaned[name_start..j].to_string();
            if name.is_empty() { idx=j; continue; }
            while j < cleaned.len() && cleaned.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            let mut bases = Vec::new();
            if j+2 < cleaned.len() && cleaned[j..].starts_with("is") {
                j+=2;
                while j < cleaned.len() && cleaned.as_bytes()[j].is_ascii_whitespace() { j+=1; }
                let bases_start = j;
                let mut brace_pos = None;
                let mut paren_depth = 0;
                while j < cleaned.len() {
                    let c = cleaned.as_bytes()[j];
                    if c==b'(' { paren_depth+=1; }
                    else if c==b')' { if paren_depth>0 { paren_depth-=1; } }
                    else if c==b'{' && paren_depth==0 { brace_pos = Some(j); break; }
                    j+=1;
                }
                if let Some(bp) = brace_pos {
                    let bases_str = cleaned[bases_start..bp].trim();
                    for base in bases_str.split(',') {
                        let base = base.trim();
                        if base.is_empty() { continue; }
                        let base_name = if let Some(p) = base.find('(') { base[..p].trim() } else { base };
                        let bn = base_name.split_whitespace().last().unwrap_or(base_name).to_string();
                        bases.push(bn);
                    }
                    j = bp;
                }
            }
            while j < cleaned.len() && cleaned.as_bytes()[j]!=b'{' { j+=1; }
            if j>=cleaned.len() { break; }
            let body_start = j+1;
            let mut depth=1;
            let mut k=body_start;
            while k<cleaned.len() && depth>0 {
                let c=cleaned.as_bytes()[k];
                if c==b'{' { depth+=1; } else if c==b'}' { depth-=1; }
                k+=1;
            }
            let body_end = if depth==0 { k-1 } else { cleaned.len() };
            let body = cleaned[body_start..body_end].to_string();
            let contract = parse_contract_body_simple(&name, bases, &body);
            contracts.push(contract);
            idx = body_end+1;
        } else { break; }
    }
    contracts
}

fn parse_contract_body_simple(name: &str, bases: Vec<String>, body: &str) -> ContractInfo {
    let mut contract = ContractInfo {
        name: name.to_string(),
        bases,
        functions: Vec::new(),
        events: Vec::new(),
        errors: Vec::new(),
        state_vars: Vec::new(),
        structs: HashMap::new(),
        enums: HashMap::new(),
        constructor: None,
        fallback: None,
        receive: None,
    };
    let mut idx=0;
    while idx < body.len() {
        if let Some(pos) = body[idx..].find("struct") {
            let abs = idx+pos;
            if abs>0 && (body.as_bytes()[abs-1].is_ascii_alphanumeric() || body.as_bytes()[abs-1]==b'_') { idx=abs+6; continue; }
            let after = &body[abs+6..];
            let mut j=0;
            while j<after.len() && after.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            let ns=j;
            while j<after.len() && (after.as_bytes()[j].is_ascii_alphanumeric() || after.as_bytes()[j]==b'_') { j+=1; }
            let sname=after[ns..j].to_string();
            while j<after.len() && after.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            if j>=after.len() || after.as_bytes()[j]!=b'{' { idx=abs+6; continue; }
            let bs=j+1;
            let mut depth=1;
            let mut k=bs;
            while k<after.len() && depth>0 {
                if after.as_bytes()[k]==b'{' { depth+=1; } else if after.as_bytes()[k]==b'}' { depth-=1; }
                k+=1;
            }
            let sbody=after[bs..k-1].to_string();
            let mut members=Vec::new();
            for line in sbody.split(';') {
                let line=line.trim();
                if line.is_empty() { continue; }
                if let Some(last_sp) = line.rfind(|c: char| c.is_whitespace()) {
                    let mname=line[last_sp+1..].trim().to_string();
                    let mtype=line[..last_sp].trim().to_string();
                    if mname.chars().all(|c| c.is_alphanumeric()||c=='_') {
                        members.push((mname,mtype));
                    }
                }
            }
            contract.structs.insert(sname.clone(), StructInfo { members });
            idx=abs+6;
        } else { break; }
    }
    idx=0;
    while idx<body.len() {
        if let Some(pos)=body[idx..].find("enum") {
            let abs=idx+pos;
            if abs>0 && (body.as_bytes()[abs-1].is_ascii_alphanumeric()||body.as_bytes()[abs-1]==b'_') { idx=abs+4; continue; }
            let after=&body[abs+4..];
            let mut j=0;
            while j<after.len() && after.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            let ns=j;
            while j<after.len() && (after.as_bytes()[j].is_ascii_alphanumeric()||after.as_bytes()[j]==b'_') { j+=1; }
            let ename=after[ns..j].to_string();
            while j<after.len() && after.as_bytes()[j].is_ascii_whitespace() { j+=1; }
            if j>=after.len()||after.as_bytes()[j]!=b'{' { idx=abs+4; continue; }
            let bs=j+1;
            let mut depth=1;
            let mut k=bs;
            while k<after.len() && depth>0 {
                if after.as_bytes()[k]==b'{' { depth+=1; } else if after.as_bytes()[k]==b'}' { depth-=1; }
                k+=1;
            }
            let ebody=after[bs..k-1].to_string();
            let vars:Vec<String>=ebody.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
            contract.enums.insert(ename.clone(), EnumInfo { variants: vars });
            idx=abs+4;
        } else { break; }
    }
    let mut i=0;
    let blen=body.len();
    let bbytes=body.as_bytes();
    while i<blen {
        while i<blen && bbytes[i].is_ascii_whitespace() { i+=1; }
        if i>=blen { break; }
        let rem=&body[i..];
        if rem.starts_with("function") {
            if let Some((f,next)) = parse_function_simple_simple(&body, i) {
                contract.functions.push(f);
                i=next;
                continue;
            }
        } else if rem.starts_with("constructor") {
            if let Some((c,next)) = parse_constructor_simple_simple(&body, i) {
                contract.constructor=Some(c);
                i=next;
                continue;
            }
        } else if rem.starts_with("fallback") {
            if let Some((fb,next)) = parse_fallback_simple_simple(&body, i) {
                contract.fallback=Some(fb);
                i=next;
                continue;
            }
        } else if rem.starts_with("receive") {
            if let Some((rcv,next)) = parse_receive_simple_simple(&body, i) {
                contract.receive=Some(rcv);
                i=next;
                continue;
            }
        } else if rem.starts_with("event") {
            if let Some((ev,next)) = parse_event_simple_simple(&body, i) {
                contract.events.push(ev);
                i=next;
                continue;
            }
        } else if rem.starts_with("error") {
            if let Some((err,next)) = parse_error_simple_simple(&body, i) {
                contract.errors.push(err);
                i=next;
                continue;
            }
        } else if rem.starts_with("struct") || rem.starts_with("enum") || rem.starts_with("modifier") || rem.starts_with("using") {
            let mut j=i;
            let mut found_brace=false;
            while j<blen {
                if bbytes[j]==b'{' { found_brace=true; break; }
                if bbytes[j]==b';' { break; }
                j+=1;
            }
            if found_brace {
                let mut depth=1;
                j+=1;
                while j<blen && depth>0 {
                    if bbytes[j]==b'{' { depth+=1; } else if bbytes[j]==b'}' { depth-=1; }
                    j+=1;
                }
                i=j;
            } else {
                while j<blen && bbytes[j]!=b';' { j+=1; }
                if j<blen { j+=1; }
                i=j;
            }
            continue;
        } else {
            if let Some(semi) = find_next_semicolon(&body, i) {
                let line = body[i..semi+1].to_string();
                if let Some(sv) = parse_state_var_simple_simple(&line) {
                    contract.state_vars.push(sv);
                }
                i=semi+1;
                continue;
            } else { break; }
        }
        i+=1;
    }
    contract
}

fn parse_function_simple_simple(body: &str, start: usize) -> Option<(FunctionInfo, usize)> {
    let rem=&body[start..];
    let mut idx="function".len();
    while idx<rem.len() && rem.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    let name_start=idx;
    while idx<rem.len() && (rem.as_bytes()[idx].is_ascii_alphanumeric() || rem.as_bytes()[idx]==b'_') { idx+=1; }
    let fname=if name_start!=idx { rem[name_start..idx].to_string() } else { "".to_string() };
    while idx<rem.len() && rem.as_bytes()[idx].is_ascii_whitespace() { idx+=1; }
    if idx>=rem.len() || rem.as_bytes()[idx]!=b'(' { return None; }
    let ps=idx+1;
    let mut depth=1;
    let mut j=ps;
    while j<rem.len() && depth>0 {
        let c=rem.as_bytes()[j];
        if c==b'(' { depth+=1; } else if c==b')' { depth-=1; }
        j+=1;
    }
    let params_str=rem[ps..j-1].to_string();
    let mut k=j;
    while k<rem.len() && rem.as_bytes()[k].is_ascii_whitespace() { k+=1; }
    let mut sig_end=None;
    let mut brace_pos=None;
    let mut temp=k;
    let mut pd=0;
    while temp<rem.len() {
        let c=rem.as_bytes()[temp];
        if c==b'(' { pd+=1; } else if c==b')' { if pd>0 { pd-=1; } }
        else if c==b'{' && pd==0 { sig_end=Some(temp); brace_pos=Some(temp); break; }
        else if c==b';' && pd==0 { sig_end=Some(temp); break; }
        temp+=1;
    }
    let se=sig_end.unwrap_or(rem.len());
    let mods=rem[k..se].to_string();
    let vis=extract_visibility(&mods).unwrap_or("public".to_string());
    let muta=extract_mutability(&mods);
    let params=parse_params(&params_str);
    let returns_str=extract_returns(&mods);
    let returns=if returns_str.is_empty() { Vec::new() } else { parse_params(&returns_str) };
    let mut final_idx=start+se;
    if let Some(bp)=brace_pos {
        let mut depth=1;
        let mut p=start+bp+1;
        while p<body.len() && depth>0 {
            let c=body.as_bytes()[p];
            if c==b'{' { depth+=1; } else if c==b'}' { depth-=1; }
            p+=1;
        }
        final_idx=p;
    } else {
        if final_idx<body.len() && body.as_bytes()[final_idx]==b';' { final_idx+=1; }
    }
    let func=FunctionInfo {
        name: fname,
        params,
        returns,
        visibility: vis,
        mutability: muta,
        is_virtual: mods.contains("virtual"),
    };
    Some((func, final_idx))
}

