    let left = if let Some(eq)=without_semi.find('=') { without_semi[..eq].trim() } else { without_semi };
    if let Some(last_space) = left.rfind(|c: char| c.is_whitespace()) {
        let name_candidate = left[last_space+1..].trim();
        if name_candidate.chars().all(|c| c.is_alphanumeric()||c=='_') {
            let type_and_vis = left[..last_space].trim();
            let mut vis = "internal".to_string();
            let lower = type_and_vis.to_lowercase();
            if lower.contains("public") { vis="public".to_string(); }
            else if lower.contains("private") { vis="private".to_string(); }
            else if lower.contains("internal") { vis="internal".to_string(); }
            let mut type_str = type_and_vis.to_string();
            for kw in [" public", " private", " internal", " external", " constant", " immutable", " virtual", " override", " transient"] {
                type_str = type_str.replace(kw, "");
            }
            type_str = type_str.replace("override", "");
            type_str = type_str.split_whitespace().collect::<Vec<_>>().join(" ");
            if type_str.contains("address") && lower.contains("address payable") {
                if !type_str.contains("payable") {
                    type_str = type_str.replace("address", "address payable");
                }
            }
            let type_str = type_str.trim().to_string();
            if type_str.is_empty() { return None; }
            return Some(StateVarInfo { name: name_candidate.to_string(), type_str, visibility: vis });
        }
    }
