        cand = os.path.join(base_path, path)
        if os.path.exists(cand):
            return cand
    # Fallback: try current dir for bare imports (to handle some cases)
    current_dir = "." if current_file=="<stdin>" else os.path.dirname(current_file) or "."
    cand = os.path.normpath(os.path.join(current_dir, path))
    if os.path.exists(cand):
        return cand
    return None'''

